package com.example.securefile;

import org.springframework.util.StringUtils;

import java.util.List;

/**
 * Validator zur Überprüfung der Dateiendung basierend auf einer Whitelist.
 * Verhindert das Ausliefern von potenziell gefährlichen Dateitypen (CWE-434).
 */
public class FileNameValidator {

    /**
     * Prüft, ob die Dateiendung in der Whitelist enthalten ist.
     *
     * @param fileName Der Name der Datei (inklusive Endung)
     * @return true, wenn die Dateiendung erlaubt ist
     * @throws SecureFileAccessDeniedException Wenn die Dateiendung nicht erlaubt ist
     */
    public boolean isValidExtension(String fileName) {
        if (!StringUtils.hasText(fileName)) {
            return false;
        }

        int lastDotIndex = fileName.lastIndexOf('.');
        if (lastDotIndex == -1 || lastDotIndex == fileName.length() - 1) {
            return false;
        }

        String extension = fileName.substring(lastDotIndex).toLowerCase();

        // Prüfen gegen die Whitelist aus der Konfiguration
        return SecureFileConfig.ALLOWED_EXTENSIONS.contains(extension);
    }
}
