"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureFileService.java
package com.example.securefile;

import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

/**
 * Service für sichere Dateiladeoperationen.
 * Implementiert die Regeln von CERT IDS02-J zur Pfad-Kanonisierung.
 */
@Service
public class SecureFileService {

    private static final Pattern SAFE_FILENAME_PATTERN = Pattern.compile("^[a-zA-Z0-9._-]+$");
    private final FileNameValidator fileNameValidator;

    public SecureFileService(FileNameValidator fileNameValidator) {
        this.fileNameValidator = fileNameValidator;
    }

    /**
     * Lädt eine Datei sicher aus dem Basisverzeichnis.
     *
     * @param fileName Der Name der Datei aus dem Query-Parameter
     * @return InputStream zum Lesen des Dateiinhalts
     * @throws SecureFileAccessDeniedException Bei Sicherheitsverstößen
     * @throws IOException                    Bei Lese-Fehlern
     */
    public InputStream loadFile(String fileName) throws IOException {
        // 1. Eingabevalidierung: Leere Namen ablehnen
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new SecureFileAccessDeniedException("Dateiname darf nicht leer sein.");
        }

        // 2. Entferne alle Pfadtrenner und extrahiere reinen Dateinamen
        // Verhindert jegliche Pfadkomponenten wie "/", "\", ".."
        String cleanFileName = fileName.replace('/', File.separatorChar)
                                       .replace('\\', File.separatorChar)
                                       .replace(File.separatorChar, '_');

        // 3. Extrahiere NUR den Dateinamen ohne Pfadkomponenten
        Path pathObj = Paths.get(cleanFileName);
        String safeFileName = pathObj.getFileName() != null ? pathObj.getFileName().toString() : "";

        // 4. Prüfe ob der extrahierte Name identisch mit dem bereinigten Original ist
        // Falls nicht, wurde ein Pfad versucht (z.B. "../malicious.txt")
        if (!safeFileName.equals(cleanFileName)) {
            throw new SecureFileAccessDeniedException("Unerlaubte Pfadkomponenten im Dateinamen erkannt.");
        }

        // 5. Whitelist-Check: Nur erlaubte Endungen zulassen
        if (!fileNameValidator.isValidExtension(safeFileName)) {
            throw new SecureFileAccessDeniedException("Nicht erlaubte Dateiendung: " + safeFileName);
        }

        // 6. Zusätzliche Prüfung auf verbotene Zeichen im Dateinamen (CWE-22 Mitigation)
        // Erlaubt nur alphanumerische Zeichen, Punkte, Unterstriche und Bindestriche
        if (!SAFE_FILENAME_PATTERN.matcher(safeFileName).matches()) {
            throw new SecureFileAccessDeniedException("Verbotene Zeichen im Dateinamen erkannt.");
        }

        // 7. Pfad-Konstruktion relativ zum sicheren Basisverzeichnis
        Path baseDir = Paths.get(SecureFileConfig.UPLOADS_BASE_DIR).toAbsolutePath().normalize();

        // WICHTIG: Vor der Validierung muss das Basisverzeichnis selbst existieren und lesbar sein
        if (!Files.exists(baseDir) || !Files.isDirectory(baseDir)) {
            throw new SecureFileAccessDeniedException("Basisverzeichnis existiert nicht.");
        }

        // 8. Kanonisierung des Pfades (CERT IDS02-J)
        // resolve kombiniert den Basispfad mit dem Dateinamen
        // normalize löst "..", "." und symbolische Links auf
        Path requestedPath = baseDir.resolve(safeFileName).normalize();

        // 9. Sicherheitsprüfung: Der kanonisierte Pfad MUSS im Basisverzeichnis beginnen
        // Path.startsWith ist sicherer als String.startsWith da es Pfadseparator korrekt behandelt
        if (!requestedPath.startsWith(baseDir) 
                && !requestedPath.equals(baseDir)) {
            throw new SecureFileAccessDeniedException("Zugriff verweigert: Pfad-Traversierungsversuch erkannt.");
        }

        // 10. Existenzprüfung vor dem Öffnen
        if (!Files.exists(requestedPath) || !Files.isRegularFile(requestedPath)) {
            throw new SecureFileAccessDeniedException("Datei nicht gefunden.");
        }

        // 11. Datei öffnen (nur nach erfolgreicher Validierung)
        return Files.newInputStream(requestedPath);
    }
}
