"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileDownloadController.java
package com.example.securefile;

import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;

/**
 * REST Controller für den sicheren Dateidownload.
 * Setzt Header korrekt und behandelt Exceptions.
 */
@RestController
public class FileDownloadController {

    private final SecureFileService secureFileService;

    public FileDownloadController(SecureFileService secureFileService) {
        this.secureFileService = secureFileService;
    }

    /**
     * Endpunkt zum Herunterladen einer Datei.
     *
     * @param fileName Der Name der herunterzuladenden Datei (Query Parameter)
     * @return ResponseEntity mit dem Dateistrom als Body
     */
    @GetMapping("/api/files/download")
    public ResponseEntity<byte[]> downloadFile(@RequestParam("fileName") String fileName) {
        try {
            // Datei laden (kann Exception werfen bei Sicherheitsverletzung)
            InputStream inputStream = secureFileService.loadFile(fileName);

            // Inhalt in Byte-Array lesen (für einfache Response)
            byte[] fileContent = inputStream.readAllBytes();
            inputStream.close();

            // Bestimmung des Content-Type basierend auf der Dateiendung (vereinfacht)
            MediaType contentType = getContentTypeFromFileName(fileName);

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(contentType);
            headers.setContentDispositionFormData("attachment", fileName);

            return ResponseEntity.ok()
                    .headers(headers)
                    .body(fileContent);

        } catch (SecureFileAccessDeniedException e) {
            // Sicherheitsfehler: 403 Forbidden
            return ResponseEntity.status(403)
                    .body(e.getMessage().getBytes(StandardCharsets.UTF_8));
        } catch (IOException e) {
            // Technischer Fehler: 500 Internal Server Error
            return ResponseEntity.status(500)
                    .body(("Fehler beim Lesen der Datei: " + e.getMessage()).getBytes(StandardCharsets.UTF_8));
        }
    }

    /**
     * Hilfmethode zur Bestimmung des MIME-Typs basierend auf der Erweiterung.
     * Stellt sicher, dass nur bekannte Typen zurückgegeben werden.
     */
    private MediaType getContentTypeFromFileName(String fileName) {
        if (fileName.endsWith(".pdf")) return MediaType.APPLICATION_PDF;
        if (fileName.endsWith(".txt")) return MediaType.TEXT_PLAIN;
        if (fileName.endsWith(".png")) return MediaType.IMAGE_PNG;
        if (fileName.endsWith(".jpg") || fileName.endsWith(".jpeg")) return MediaType.IMAGE_JPEG;
        if (fileName.endsWith(".gif")) return MediaType.IMAGE_GIF;
        // Fallback für unbekannte aber erlaubte Typen (falls Whitelist erweitert wurde)
        return MediaType.APPLICATION_OCTET_STREAM;
    }
}
