package com.example.security.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * Konfigurationsklasse für die Dateispeicherung.
 * Definiert den sicheren Basispfad, auf den der Zugriff beschränkt ist.
 */
@Component
@ConfigurationProperties(prefix = "app.storage")
public class FileStorageProperties {

    /**
     * Der absolute Basispfad, unter dem Dateien gespeichert sind.
     * Dieser Pfad muss physisch existieren und darf keine Schreibrechte für den Webserver haben,
     * wenn nur Lesezugriff gewünscht ist.
     */
    private String baseDir;

    public String getBaseDir() {
        return baseDir;
    }

    public void setBaseDir(String baseDir) {
        this.baseDir = baseDir;
    }
}
