package com.example.security.service;

import com.example.security.config.FileStorageProperties;
import com.example.security.exception.FileDownloadException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.core.io.UrlResource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.net.MalformedURLException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;

/**
 * Service für sichere Dateizugriffe.
 * Implementiert die Logik zur Verhinderung von Path Traversal (CWE-22).
 */
@Service
public class SecureFileService {

    private static final Logger logger = LoggerFactory.getLogger(SecureFileService.class);
    private final FileStorageProperties storageProperties;

    public SecureFileService(FileStorageProperties storageProperties) {
        this.storageProperties = storageProperties;
    }

    /**
     * Holt eine Datei sicher zurück.
     *
     * @param fileName Der vom Benutzer angegebene Dateiname.
     * @return Resource Objekt für den Stream.
     * @throws FileDownloadException Wenn der Pfad unsicher ist oder die Datei nicht existiert.
     */
    public Resource loadFileAsResource(String fileName) throws FileDownloadException {
        // 1. Validierung des Eingabeparameters (Defense in Depth)
        if (fileName == null || fileName.trim().isEmpty()) {
            throw new FileDownloadException("Dateiname darf nicht leer sein.");
        }

        // 2. Sicherstellung, dass keine ungültigen Zeichen enthalten sind (z.B. Null-Bytes)
        if (fileName.contains("\0")) {
            throw new FileDownloadException("Ungültige Zeichen im Dateinamen.");
        }

        try {
            // 3. Auflösung des Basispfades (Canonical Path)
            // Dies ist entscheidend für die Sicherheit. Wir müssen den absoluten Pfad kennen.
            Path basePath = Paths.get(storageProperties.getBaseDir()).toAbsolutePath();

            // Prüfen, ob der Basispfad existiert
            if (!Files.exists(basePath)) {
                throw new FileDownloadException("Konfiguriertes Speicherverzeichnis existiert nicht.");
            }

            // 4. Zusammenbau des Zielpfades
            // Wir nutzen Paths.get(), um den relativen Pfad des Benutzers zum Basispfad hinzuzufügen.
            Path targetPath = basePath.resolve(fileName).normalize();

            // 5. Kritischer Sicherheitscheck: Pfad-Traversierungs-Prüfung
            // Wir prüfen, ob der aufgelöste Zielpfad MITTELS des Basispfades beginnt.
            // Da wir normalize() verwendet haben, sind ../ Sequenzen bereits bereinigt, 
            // aber der Prefix-Check ist die letzte Verteidigungslinie.
            if (!targetPath.startsWith(basePath)) {
                logger.warn("Zugriffsversuch außerhalb des erlaubten Verzeichnisses abgelehnt: {}", fileName);
                throw new FileDownloadException("Zugriff verweigert: Ungültiger Dateipfad.");
            }

            // 6. Existenzprüfung
            if (!Files.exists(targetPath)) {
                throw new FileDownloadException("Datei nicht gefunden.");
            }

            // 7. Leseberechtigung prüfen
            if (!Files.isReadable(targetPath)) {
                throw new FileDownloadException("Datei ist nicht lesbar.");
            }

            // 8. Rückgabe als UrlResource
            // Hinweis: In Produktionsumgebungen sollte man ggf. NIO Streams nutzen, 
            // um Memory-Leaks bei großen Dateien zu vermeiden, aber UrlResource ist für kleine Dateien OK.
            return new UrlResource(targetPath.toUri());

        } catch (MalformedURLException e) {
            logger.error("Fehler bei der URL-Erstellung für Datei: {}", fileName, e);
            throw new FileDownloadException("Interner Serverfehler.", e);
        } catch (IOException e) {
            logger.error("Fehler beim Lesen der Datei: {}", fileName, e);
            throw new FileDownloadException("Fehler beim Laden der Datei.", e);
        }
    }
}
