package com.example.security.controller;

import com.example.security.exception.FileDownloadException;
import com.example.security.service.SecureFileService;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

/**
 * REST Controller für den sicheren Dateidownload.
 * Stellt sicher, dass alle Anfragen über den SecureFileService laufen.
 */
@RestController
public class FileDownloadController {

    private final SecureFileService secureFileService;

    public FileDownloadController(SecureFileService secureFileService) {
        this.secureFileService = secureFileService;
    }

    /**
     * Endpunkt zum Herunterladen von Dateien.
     *
     * @param file Der Dateiname als Query-Parameter.
     * @return ResponseEntity mit dem Dateistream und korrekten Headern.
     */
    @GetMapping("/api/files/download")
    public ResponseEntity<?> downloadFile(@RequestParam("file") String file) {
        try {
            var resource = secureFileService.loadFileAsResource(file);

            // Bestimmung des Dateinamens für den Content-Disposition Header
            String fileName = resource.getFilename();
            if (fileName == null) {
                fileName = "download";
            }

            // Aufbau der Response
            return ResponseEntity.ok()
                    .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + fileName + "\"")
                    .contentType(MediaType.APPLICATION_OCTET_STREAM)
                    .contentLength(Files.size(resource.getFile().toPath()))
                    .body(resource);

        } catch (FileDownloadException e) {
            // Sicherheitsrelevante Fehler werden hier behandelt, ohne interne Stacktraces preiszugeben
            return ResponseEntity.status(403).body(e.getMessage());
        } catch (Exception e) {
            // Generic Error Handling
            return ResponseEntity.status(500).body("Ein unerwarteter Fehler ist aufgetreten.");
        }
    }
}
