"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimiter.java
package com.example.security.ping;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Einfacher, thread-sicherer Rate Limiter basierend auf einem Token-Bucket-Algorithmus.
 * Verhindert Missbrauch durch zu viele Anfragen innerhalb eines Zeitfensters.
 * 
 * Sicherheitshinweis: In einer Produktionsumgebung sollte dieser Mechanismus idealerweise
 * auf Redis oder einem Load Balancer laufen, um auch bei mehreren Serverinstanzen konsistent zu sein.
 */
public class RateLimiter {

    // Konfiguration: Maximal 5 Anfragen pro 60 Sekunden pro Client
    private static final int MAX_REQUESTS = 5;
    private static final long TIME_WINDOW_MS = 60_000L; 

    // Speichert Timestamps der letzten Anfragen pro Client-ID
    private final Map<String, Long> lastRequestTime = new ConcurrentHashMap<>();
    private final Map<String, AtomicLong> requestCount = new ConcurrentHashMap<>();

    /**
     * Prüft, ob eine Anfrage erlaubt ist.
     * @param clientId Unique Identifier des Clients (z.B. IP-Adresse)
     * @return true wenn erlaubt, false wenn limitiert
     */
    public boolean tryAcquire(String clientId) {
        long now = System.currentTimeMillis();

        // Hole existierende Zähler oder erstelle neuen
        AtomicLong count = requestCount.computeIfAbsent(clientId, k -> new AtomicLong(0));
        long lastTime = lastRequestTime.getOrDefault(clientId, 0L);

        synchronized (this) {
            // Wenn Zeitfenster abgelaufen ist, zurücksetzen
            if (now - lastTime > TIME_WINDOW_MS) {
                count.set(1);
                lastRequestTime.put(clientId, now);
                return true;
            } else {
                // Innerhalb des Fensters prüfen
                if (count.get() < MAX_REQUESTS) {
                    count.incrementAndGet();
                    return true;
                } else {
                    return false;
                }
            }
        }
    }

    /**
     * Bereinigt alte Einträge, um Speicherlecks zu vermeiden.
     * Sollte periodisch aufgerufen werden.
     */
    public void cleanup() {
        long now = System.currentTimeMillis();
        lastRequestTime.entrySet().removeIf(entry -> (now - entry.getValue()) > TIME_WINDOW_MS * 2);
        requestCount.entrySet().removeIf(entry -> !lastRequestTime.containsKey(entry.getKey()));
    }
}
