"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PingService.java
package com.example.security.ping;

import java.io.IOException;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.regex.Pattern;

/**
 * Service für die Ausführung von Ping-Befehlen.
 * Nutzt Java Networking API statt OS Commands zur Vermeidung von Command Injection.
 */
public class PingService {

    private final RateLimiter rateLimiter;

    // Regex-Whitelist: Erlaubt nur Hostnamen und IPv4-Adressen.
    // Keine Leerzeichen, keine Shell-Metazeichen (; | & $ ` \ etc.)
    private static final Pattern HOSTNAME_PATTERN = Pattern.compile(
        "^([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])(\\.([a-zA-Z0-9]|[a-zA-Z0-9][a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9]))*$"
    );

    // Maximale Anzahl von Pings pro Anfrage (verhindert Ressourcenerschöpfung)
    private static final int MAX_PING_COUNT = 5;
    private static final int MIN_PING_COUNT = 1;
    // Timeout pro Ping-Anfrage in Millisekunden (ersetzt Prozess-Timeout)
    private static final int PING_TIMEOUT_MS = 2000; 

    public PingService(RateLimiter rateLimiter) {
        this.rateLimiter = rateLimiter;
    }

    /**
     * Führt den Ping durch, nachdem alle Sicherheitschecks bestanden wurden.
     * Nutzt InetAddress.isReachable() um OS Command Injection zu vermeiden.
     * @param clientId Identifikation des Clients (für Rate Limiting)
     * @param target Zielhost
     * @param count Anzahl der Pings
     * @return Ergebnis als String
     * @throws PingException bei Validierungsfehlern oder Prozessfehlern
     */
    public String executePing(String clientId, String target, int count) throws PingException {

        // 1. Rate Limiting prüfen (CWE-400)
        if (!rateLimiter.tryAcquire(clientId)) {
            throw new PingException("Zu viele Anfragen. Bitte warten Sie.");
        }

        // 2. Validierung des Targets (CWE-78)
        if (target == null || target.trim().isEmpty()) {
            throw new PingException("Zielhost darf nicht leer sein.");
        }
        if (!HOSTNAME_PATTERN.matcher(target).matches()) {
            throw new PingException("Ungültiges Format für Zielhost. Nur alphanumerische Zeichen, Punkte und Bindestriche erlaubt.");
        }

        // 3. Validierung des Count (CWE-190)
        if (count < MIN_PING_COUNT || count > MAX_PING_COUNT) {
            throw new PingException("Anzahl der Pings muss zwischen " + MIN_PING_COUNT + " und " + MAX_PING_COUNT + " liegen.");
        }

        // 4. Sichere Netzwerkprüfung (Java Native API statt OS Command)
        // Verwendet InetAddress.isReachable() statt ProcessBuilder, um CWE-78 zu eliminieren.
        StringBuilder output = new StringBuilder();
        boolean allSuccess = true;
        int successfulPings = 0;

        try {
            InetAddress address = InetAddress.getByName(target);

            for (int i = 0; i < count; i++) {
                // isReachable führt einen ICMP Echo Request aus
                // Timeout ist in Millisekunden
                boolean reachable = address.isReachable(PING_TIMEOUT_MS);

                if (reachable) {
                    successfulPings++;
                    output.append("Ping ").append(i + 1).append(": Erfolgreich\n");
                } else {
                    allSuccess = false;
                    output.append("Ping ").append(i + 1).append(": Zeitüberschreitung oder Paketverlust\n");
                }
            }

            if (!allSuccess) {
                 throw new PingException("Nicht alle Pings waren erfolgreich. Erfolge: " + successfulPings + "/" + count + "\n" + output.toString());
            }

            return "Alle " + count + " Pings erfolgreich.\n" + output.toString();

        } catch (UnknownHostException e) {
            throw new PingException("Zielhost konnte nicht aufgelöst werden.", e);
        } catch (IOException e) {
            throw new PingException("Fehler beim Ausführen des Ping-Vorgangs.", e);
        }
    }
}
