"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PingController.java
package com.example.security.ping;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

import javax.servlet.http.HttpServletRequest;

/**
 * REST Controller für den Ping-Endpoint.
 * Delegiert die Verarbeitung an den Service und behandelt HTTP-spezifische Aspekte.
 */
@RestController
public class PingController {

    private final PingService pingService;

    @Autowired
    public PingController(PingService pingService) {
        this.pingService = pingService;
    }

    /**
     * GET /tools/ping
     * 
     * @param target Zielhost oder IP-Adresse
     * @param count Anzahl der Pings (optional, Default: 1)
     * @return Ping-Ergebnis als Plain Text
     */
    @GetMapping("/tools/ping")
    public ResponseEntity<String> ping(@RequestParam String target, 
                                       @RequestParam(defaultValue = "1") int count) {

        try {
            // Client-IP aus Request holen für Rate Limiting
            HttpServletRequest request = ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest();
            String clientIp = getClientIp(request);

            // Aufruf des Services mit allen Sicherheitschecks
            String result = pingService.executePing(clientIp, target, count);

            return ResponseEntity.ok(result);

        } catch (PingException e) {
            // Sicherer Umgang mit Validierungsfehlern
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
        } catch (Exception e) {
            // Interner Server Error, aber ohne sensible Details preiszugeben
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body("Ein interner Fehler ist aufgetreten.");
        }
    }

    /**
     * Hilfmethode zur Extraktion der Client-IP Adresse.
     * Berücksichtigt Proxy-Falls (X-Forwarded-For).
     */
    private String getClientIp(HttpServletRequest request) {
        String ip = request.getHeader("X-Forwarded-For");
        if (ip == null || ip.isEmpty() || "unknown".equalsIgnoreCase(ip)) {
            ip = request.getHeader("Proxy-Client-IP");
        }
        if (ip == null || ip.isEmpty() || "unknown".equalsIgnoreCase(ip)) {
            ip = request.getHeader("WL-Proxy-Client-IP");
        }
        if (ip == null || ip.isEmpty() || "unknown".equalsIgnoreCase(ip)) {
            ip = request.getRemoteAddr();
        }
        // Falls mehrere IPs im Header, nimm die erste
        if (ip != null && ip.contains(",")) {
            ip = ip.split(",")[0];
        }
        return ip;
    }
}
