"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitService.java
package com.example.secureguestbook;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Einfacher Rate-Limiter basierend auf einem ConcurrentHashMap.
 * In Produktion sollte Redis oder Guava RateLimiter verwendet werden.
 */
@Service
public class RateLimitService {

    private static final Logger logger = LoggerFactory.getLogger(RateLimitService.class);
    private static final int MAX_REQUESTS = 100;
    private static final long TIME_WINDOW_MS = 60000; // 1 Minute

    private final Map<String, AtomicInteger> requestCounts = new ConcurrentHashMap<>();
    private final Map<String, Long> windowStartTimes = new ConcurrentHashMap<>();

    public boolean isAllowed(String ipAddress) {
        if (!isValidIpAddress(ipAddress)) {
            logger.warn("Invalid IP address format detected");
            return false;
        }

        Long now = System.currentTimeMillis();
        AtomicInteger count = requestCounts.computeIfAbsent(ipAddress, k -> new AtomicInteger(0));
        Long startTime = windowStartTimes.getOrDefault(ipAddress, now);

        // Fenster zurücksetzen, wenn abgelaufen
        if (now - startTime > TIME_WINDOW_MS) {
            count.set(0);
            windowStartTimes.put(ipAddress, now);
        }

        int currentCount = count.incrementAndGet();
        if (currentCount > MAX_REQUESTS) {
            logger.warn("Rate limit exceeded for IP: {}", sanitizeForLogging(ipAddress));
            return false;
        }
        return true;
    }

    public String getClientIp(org.springframework.http.HttpHeaders headers) {
        String ip = headers.getFirst("X-Forwarded-For");
        if (ip == null || ip.isEmpty()) {
            ip = headers.getFirst("X-Real-IP");
        }
        if (ip == null || ip.isEmpty()) {
            ip = "unknown";
        } else {
            // X-Forwarded-For kann mehrere IPs enthalten, erste ist Client
            ip = ip.split(",")[0].trim();
        }
        return ip;
    }

    /**
     * Validiert die IP-Adresse und entfernt potenziell schädliche Zeichen
     */
    private boolean isValidIpAddress(String ip) {
        if (ip == null || ip.isEmpty()) {
            return false;
        }

        // Entferne alle CRLF-Zeichen
        ip = ip.replaceAll("[\\r\\n]", "");

        // Prüfe ob nur gültige IP-Zeichen vorhanden sind (Zahlen, Punkte, Doppelpunkte für IPv6)
        return ip.matches("^([0-9]{1,3}\\.){3}[0-9]{1,3}$|([0-9a-fA-F]{0,4}:){2,7}[0-9a-fA-F]{0,4}$");
    }

    /**
     * Sanitisiert den String für Logging-Zwecke
     */
    private String sanitizeForLogging(String input) {
        if (input == null) {
            return "";
        }
        // Entferne alle CRLF-Zeichen um Log-Injection zu verhindern
        return input.replaceAll("[\\r\\n]", "");
    }
}
