package com.example.secureguestbook;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Service Layer für Geschäftslogik.
 * Enthält Validierungslogik und Aufruf der Repositories.
 */
@Service
public class GuestbookService {

    private static final Logger logger = LoggerFactory.getLogger(GuestbookService.class);
    private static final Pattern NAME_PATTERN = Pattern.compile("^[a-zA-Z0-9\\s\\-]{1,50}$");
    private static final Pattern TEXT_PATTERN = Pattern.compile("^[a-zA-Z0-9\\s\\p{Punct}\\-\\._,!?]{1,500}$");

    @Autowired
    private GuestbookRepository repository;

    @Autowired
    private EncryptionService encryptionService;

    @Transactional
    public GuestbookEntity createEntry(GuestbookDTO dto) {
        // Input Validation (Allowlist Ansatz)
        if (!isValidName(dto.getName())) {
            throw new IllegalArgumentException("Ungültiger Name");
        }
        if (!isValidText(dto.getText())) {
            throw new IllegalArgumentException("Ungültiger Text");
        }

        try {
            // Verschlüsselung sensibler Daten vor Speicherung
            String encryptedText = encryptionService.encrypt(dto.getText());

            GuestbookEntity entity = new GuestbookEntity(dto.getName(), encryptedText);
            logger.info("Neuer Eintrag erstellt für User: {}", dto.getName()); // Parametrisiertes Logging
            return repository.save(entity);
        } catch (Exception e) {
            logger.error("Fehler beim Speichern des Eintrags", e);
            throw new RuntimeException("Speichern fehlgeschlagen", e);
        }
    }

    public List<GuestbookEntity> getAllEntries() {
        return repository.findAllByOrderByCreatedAtDesc();
    }

    private boolean isValidName(String name) {
        if (name == null || name.length() > 50) return false;
        return NAME_PATTERN.matcher(name).matches();
    }

    private boolean isValidText(String text) {
        if (text == null || text.length() > 500) return false;
        return TEXT_PATTERN.matcher(text).matches();
    }
}
