"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitFilter.java
package com.example.secureguestbook;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException;

/**
 * Custom Filter für Rate Limiting.
 * Blockiert Requests, die das Limit überschreiten.
 */
@Component
public class RateLimitFilter extends OncePerRequestFilter {

    @Autowired
    private RateLimitService rateLimitService;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {

        String clientIp = rateLimitService.getClientIp(request.getHeaderNames().asIterator());
        // Fallback falls Header leer sind
        if (clientIp.equals("unknown")) {
             clientIp = request.getRemoteAddr();
        }

        if (!rateLimitService.isAllowed(clientIp)) {
            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            response.getWriter().write("Zu viele Anfragen.");
            return;
        }

        filterChain.doFilter(request, response);
    }
}
