package com.example.secureapp.repository;

import com.example.secureapp.model.Customer;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Repository für Datenbankzugriffe.
 * Nutzt JPQL mit benannten Parametern (:searchTerm), um SQL-Injection (CWE-89) zu verhindern.
 * Der Suchbegriff wird vom Framework sicher gebunden.
 */
@Repository
public interface CustomerRepository extends JpaRepository<Customer, Long> {

    /**
     * Suche nach Kunden basierend auf Name, E-Mail oder Stadt.
     * Die LIKE-Abfrage wird durch den Parameterizer geschützt.
     * Wildcards (%) werden hier kontrolliert hinzugefügt, um Partial Matches zu ermöglichen.
     */
    @Query("SELECT c FROM Customer c WHERE " +
           "c.name LIKE %:searchTerm% OR " +
           "c.email LIKE %:searchTerm% OR " +
           "c.city LIKE %:searchTerm%")
    List<Customer> findCustomersBySearch(@Param("searchTerm") String searchTerm);
}
