package com.example.secureapp.service;

import com.example.secureapp.dto.CustomerResponseDto;
import com.example.secureapp.exception.ValidationException;
import com.example.secureapp.model.Customer;
import com.example.secureapp.repository.CustomerRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Service-Schicht für die Suchlogik.
 * Trennt Geschäftslogik von der Infrastruktur und führt Validierungen durch.
 */
@Service
public class CustomerSearchService {

    private final CustomerRepository customerRepository;

    public CustomerSearchService(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    /**
     * Führt die Suche durch.
     * Validiert zuerst den Input, ruft dann das Repository auf und mappet auf DTOs.
     */
    @Transactional(readOnly = true)
    public List<CustomerResponseDto> searchCustomers(String searchTerm) {
        // 1. Validierung der Eingabe (Defense in Depth)
        if (searchTerm == null || searchTerm.trim().isEmpty()) {
            throw new ValidationException("Suchbegriff darf nicht leer sein.");
        }

        // Begrenzung der Länge zum Schutz vor DoS-Angriffen (ReDoS oder große Abfragen)
        if (searchTerm.length() > 100) {
            throw new ValidationException("Suchbegriff ist zu lang (Max 100 Zeichen).");
        }

        // Optional: Whitelisting von Zeichen (nur Alphanumerisch, Leerzeichen, Bindestrich, Unterstrrich)
        // Dies verhindert bereits auf App-Ebene viele Injektionsversuche, bevor sie die DB erreichen.
        if (!searchTerm.matches("^[a-zA-Z0-9\\s\\-_]+$")) {
            throw new ValidationException("Unerlaubte Zeichen im Suchbegriff.");
        }

        // 2. Datenbankabfrage (Sicher durch Parameterisierung im Repository)
        List<Customer> results = customerRepository.findCustomersBySearch(searchTerm);

        // 3. Mapping auf DTOs (Verhindert Exposure interner Entity-Daten)
        return results.stream()
                .map(customer -> new CustomerResponseDto(
                        customer.getId(),
                        customer.getName(),
                        customer.getEmail(),
                        customer.getCity()
                ))
                .collect(Collectors.toList());
    }
}
