package com.example.secureapp.controller;

import com.example.secureapp.dto.CustomerResponseDto;
import com.example.secureapp.exception.ValidationException;
import com.example.secureapp.service.CustomerSearchService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/**
 * REST Controller für die Kundensuche.
 * Dekodiert URL-Parameter und delegiert an den Service.
 */
@RestController
@RequestMapping("/api/v1/customers")
public class CustomerSearchController {

    private final CustomerSearchService customerSearchService;

    public CustomerSearchController(CustomerSearchService customerSearchService) {
        this.customerSearchService = customerSearchService;
    }

    /**
     * Endpunkt für die Suche.
     * Akzeptiert einen 'search' Query Parameter.
     * Spring MVC decodiert den Parameter automatisch, weitere Validierung erfolgt im Service.
     */
    @GetMapping("/search")
    public ResponseEntity<List<CustomerResponseDto>> searchCustomers(
            @RequestParam(value = "search", required = true) String search) {

        try {
            List<CustomerResponseDto> results = customerSearchService.searchCustomers(search);
            return ResponseEntity.ok(results);
        } catch (ValidationException e) {
            // Logge den Fehler sicher (nicht an Client weitergeben, falls sensible Details enthalten wären)
            // In Produktion: Logger.log(e.getMessage());
            return ResponseEntity.badRequest().body(null); 
        } catch (Exception e) {
            // Generic Error Handling
            return ResponseEntity.internalServerError().body(null);
        }
    }
}
