"}, {"type": "CODE_BLOCK", "language": "java", "content": "// LdapUserService.java
package com.example.security.service;

import com.example.security.dto.UserResponseDto;
import com.example.security.exception.InvalidLdapInputException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.ldap.core.ContextMapper;
import org.springframework.ldap.core.DirContextOperations;
import org.springframework.ldap.core.LdapTemplate;
import org.springframework.stereotype.Service;

import javax.naming.NamingEnumeration;
import javax.naming.NamingException;
import javax.naming.directory.SearchControls;
import javax.naming.directory.SearchResult;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Service-Klasse für sichere LDAP-Abfragen.
 * Implementiert Defense-in-Depth Strategien gegen LDAP Injection.
 */
@Service
public class LdapUserService {

    // Regex für Allow-List Input Validation.
    // Erlaubt nur alphanumerische Zeichen, Unterstriche, Bindestriche und Punkte.
    // Dies verhindert LDAP Metacharakter wie *, (, ), \, NUL bereits im Vorfeld.
    private static final Pattern USERNAME_PATTERN = Pattern.compile("^[a-zA-Z0-9._-]+$");

    private final LdapTemplate ldapTemplate;

    @Autowired
    public LdapUserService(LdapTemplate ldapTemplate) {
        this.ldapTemplate = ldapTemplate;
    }

    /**
     * Sucht Benutzer basierend auf dem Benutzernamen.
     *
     * @param username Der vom Client angegebene Benutzername.
     * @return Liste der gefundenen Benutzer.
     * @throws InvalidLdapInputException Wenn der Input ungültig ist.
     */
    public List<UserResponseDto> findUsersByUsername(String username) {
        // 1. Null-Check und Allow-List Validation (Primary Defense)
        if (username == null || !USERNAME_PATTERN.matcher(username).matches()) {
            throw new InvalidLdapInputException("Ungültiger Benutzername. Nur alphanumerische Zeichen, ., -, _ erlaubt.");
        }

        // 2. Verwendung von Parameterisierten Abfragen (Prepared Statements für LDAP)
        // Spring LDAP unterstützt Platzhalter {0}, {1} im Filterstring.
        // Diese werden sicher durch den Framework intern gescapet (RFC4515 compliant).
        // Dies eliminiert das Risiko von LDAP Injection durch String-Konkatenation.
        String filter = "(&(uid={0})(objectClass=person))";
        Object[] params = new Object[]{username};

        // 3. Suche durchführen
        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        // Attribute zu laden, die wir benötigen
        controls.setReturningAttributes(new String[]{"uid", "displayName", "mail", "department"});

        try {
            NamingEnumeration<SearchResult> results = ldapTemplate.search(
                "ou=users,dc=example,dc=com", // Base DN (muss angepasst werden)
                filter,
                params,
                createUserMapper()
            );

            List<UserResponseDto> userList = new ArrayList<>();
            while (results.hasMore()) {
                userList.add(results.next());
            }
            return userList;
        } catch (NamingException e) {
            // Logging sollte hier erfolgen (nicht an Client weitergeben)
            throw new RuntimeException("Fehler bei der LDAP-Abfrage", e);
        }
    }

    /**
     * Mapper Funktion, um LDAP-Ergebnisse in DTOs zu transformieren.
     */
    private ContextMapper<UserResponseDto> createUserMapper() {
        return (DirContextOperations item) -> {
            String uid = item.getStringAttribute("uid");
            String displayName = item.getStringAttribute("displayName");
            String mail = item.getStringAttribute("mail");
            String department = item.getStringAttribute("department");

            // Fallback für leere Werte
            return new UserResponseDto(
                uid != null ? uid : "",
                displayName != null ? displayName : "",
                mail != null ? mail : "",
                department != null ? department : ""
            );
        };
    }
}
