package com.example.security.controller;

import com.example.security.dto.UserResponseDto;
import com.example.security.exception.InvalidLdapInputException;
import com.example.security.service.LdapUserService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Collections;
import java.util.List;

/**
 * REST Controller für LDAP-Abfragen.
 * Delegiert Validierung und Logik an den Service.
 */
@RestController
@RequestMapping("/directory")
public class DirectoryUserController {

    private final LdapUserService ldapUserService;

    public DirectoryUserController(LdapUserService ldapUserService) {
        this.ldapUserService = ldapUserService;
    }

    /**
     * GET /directory/users
     * Ruft Benutzerdaten aus dem LDAP ab.
     *
     * @param username Query Parameter für die Suche.
     * @return ResponseEntity mit Liste der Benutzer oder Fehlerstatus.
     */
    @GetMapping("/users")
    public ResponseEntity<List<UserResponseDto>> getUsers(@RequestParam("username") String username) {
        try {
            List<UserResponseDto> users = ldapUserService.findUsersByUsername(username);
            return ResponseEntity.ok(users);
        } catch (InvalidLdapInputException e) {
            // 400 Bad Request für ungültige Eingabe
            return ResponseEntity.badRequest().body(Collections.emptyList());
        } catch (RuntimeException e) {
            // 500 Internal Server Error für Systemfehler
            // Stacktrace darf NICHT an den Client gesendet werden!
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Collections.emptyList());
        }
    }
}
