"}, {"type": "CODE_BLOCK", "language": "java", "content": "// LdapSecurityConfig.java
package com.example.security.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.ldap.core.support.LdapContextSource;

import javax.naming.Context;
import java.util.Properties;

/**
 * Konfiguration für die LDAP-Verbindung.
 * Wichtigste Sicherheitsmaßnahme: Least Privilege beim Binden.
 * Es wird ein dedizierter Dienstaccount verwendet, nicht Anonymous oder Admin.
 */
@Configuration
public class LdapSecurityConfig {

    /**
     * Erstellt den LdapContextSource.
     * In einer echten Umgebung sollten diese Werte aus Environment Variables oder einem Secrets Manager kommen.
     */
    @Bean
    public LdapContextSource ldapContextSource() {
        LdapContextSource contextSource = new LdapContextSource();

        // URL des LDAP Servers
        contextUrl(contextSource);

        // Credentials für den Dienstaccount (Least Privilege)
        // Dieser Account darf nur lesen (Read-Only) und nur in der OU=users
        baseDn(contextSource);
        credentials(contextSource);

        // SSL/TLS erzwingen für Transportverschlüsselung
        environment(contextSource);

        return contextSource;
    }

    private void contextUrl(LdapContextSource contextSource) {
        // Beispiel-URL, muss an die Infrastruktur angepasst werden
        contextSource.setUrl("ldaps://ldap.company.com:636"); 
    }

    private void baseDn(LdapContextSource contextSource) {
        contextSource.setBase("dc=company,dc=com");
    }

    private void credentials(LdapContextSource contextSource) {
        // Dient als technischer Account für die App, nicht als Admin
        contextSource.setPassword("secure-service-account-password");
        contextSource.setUsername("cn=app-reader,ou=services,dc=company,dc=com");
    }

    private void environment(LdapContextSource contextSource) {
        Properties env = new Properties();
        // Erzwingt SSL/TLS (LDAPS)
        env.put(Context.SECURITY_PROTOCOL, "ssl");
        // Truststore Konfiguration könnte hier hinzugefügt werden
        contextSource.setEnvironment(env);
    }
}
