"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExportService.java
package com.example.secureapp.service;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

/**
 * Service für sichere Dateiausgaben.
 * 
 * Sicherheitskonzepte:
 * - CWE-22 Improper Limitation of a Pathname to a Restricted Directory ('Path Traversal')
 * - CWE-36 Absolute Path Traversal
 * - CWE-200 Exposure of Sensitive Information to an Unauthorized Actor
 * 
 * Maßnahmen:
 * 1. Whitelist-Validierung des Dateinamens (keine Sonderzeichen wie / oder \).
 * 2. Auflösung des kanonischen Pfades, um Symlinks und Relative Pfade zu neutralisieren.
 * 3. Prüfung, ob der resultierende Pfad innerhalb des erlaubten Verzeichnisses liegt.
 */
@Service
public class ExportService {

    private static final Pattern FILENAME_PATTERN = Pattern.compile("^[a-zA-Z0-9._-]+$");

    // Das Basisverzeichnis, aus dem Dateien ausgelesen werden dürfen
    private final Path exportDirectory;

    public ExportService(@Value("${app.export.directory:/tmp/exports}") String exportDirString) {
        this.exportDirectory = Paths.get(exportDirString).toAbsolutePath().normalize();

        // Sicherstellen, dass das Verzeichnis existiert
        try {
            Files.createDirectories(this.exportDirectory);
        } catch (IOException e) {
            throw new IllegalStateException("Export-Verzeichnis konnte nicht initialisiert werden", e);
        }
    }

    /**
     * Prüft, ob der Dateiname sicher ist.
     * Erlaubt nur Alphanumerika, Punkte, Bindestriche und Unterstriche.
     * Verhindert damit das Einfügen von Pfadtrennern (/ oder \).
     */
    private boolean isValidFileName(String fileName) {
        if (!StringUtils.hasText(fileName)) {
            return false;
        }
        return FILENAME_PATTERN.matcher(fileName).matches();
    }

    /**
     * Holt eine Datei sicher zurück.
     * 
     * @param fileName Der angeforderte Dateiname (aus Query Parameter)
     * @return Der Pfad zur Datei, falls sicher verfügbar
     * @throws ExportException Wenn die Datei nicht existiert oder unsicher ist
     */
    public Path getSecureFile(String fileName) throws IOException {
        // 1. Validierung des Eingabeparameters (CWE-22)
        if (!isValidFileName(fileName)) {
            throw new ExportException("Ungültiger Dateiname.");
        }

        // 2. Konstruktion des Zielpfads
        Path targetPath = this.exportDirectory.resolve(fileName).normalize();

        // 3. Kritische Sicherheitsprüfung: Pfad muss innerhalb des Basisverzeichnisses liegen (CWE-36)
        // Wir nutzen getCanonicalPath(), um Symlinks aufzulösen und absolute Pfade zu erhalten.
        if (!targetPath.toRealPath().startsWith(this.exportDirectory.toRealPath())) {
            throw new ExportException("Zugriff verweigert: Datei liegt außerhalb des erlaubten Bereichs.");
        }

        // 4. Existenzprüfung
        if (!Files.exists(targetPath)) {
            throw new ExportException("Datei nicht gefunden.");
        }

        if (!Files.isRegularFile(targetPath)) {
            throw new ExportException("Keine reguläre Datei.");
        }

        return targetPath;
    }
}
