package com.example.secureapp.controller;

import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.resource.ResourceResolver;
import org.springframework.web.servlet.resource.ResourceResolverChain;
import org.springframework.web.servlet.resource.WebMvcConfigurer;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

import com.example.secureapp.service.ExportService;

/**
 * REST Controller für den Export-Endpunkt.
 * 
 * Sicherheitskonzept: A01:2025 Broken Access Control
 * - Dieser Controller erwartet eine erfolgreiche Authentifizierung (durch SecurityConfig).
 * - Delegiert die Logik an den ExportService.
 */
@RestController
@RequestMapping("/api")
public class ExportController {

    private final ExportService exportService;

    public ExportController(ExportService exportService) {
        this.exportService = exportService;
    }

    /**
     * GET /api/export
     * 
     * Lädt eine Datei herunter.
     * 
     * @param filename Der Name der Datei (Query Parameter)
     * @return Die Datei als Stream mit korrekten Download-Headern
     */
    @GetMapping("/export")
    public ResponseEntity<byte[]> exportFile(@RequestParam("filename") String filename) throws IOException {
        // Aufruf des Services, der die Sicherheit prüft
        Path filePath = exportService.getSecureFile(filename);

        byte[] fileContent = Files.readAllBytes(filePath);

        // Sichere Antwort-Header setzen
        HttpHeaders headers = new HttpHeaders();

        // Content-Disposition erzwingt Download und setzt den Namen sicher
        // Der Dateiname stammt aus dem validierten String, daher sicher
        ContentDisposition disposition = ContentDisposition.attachment()
                .filename(filename)
                .build();
        headers.setContentDisposition(disposition);

        // MIME-Type basierend auf Extension bestimmen (vereinfacht)
        headers.setContentType(MediaType.APPLICATION_OCTET_STREAM);

        return ResponseEntity.ok()
                .headers(headers)
                .body(fileContent);
    }
}
