*Korrektur für den RateLimiterService:* Der obige Entwurf war unvollständig für eine echte Zählung. Ich werde den Codeblock durch eine funktionsfähige Version ersetzen, die Zähler verwendet, um die Anforderung korrekt zu erfüllen.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimiterService.java
package com.example.security;

import org.springframework.stereotype.Service;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

@Service
public class RateLimiterService {

    // Speichert den Startzeitpunkt des aktuellen Fensters und den Zähler pro IP
    private final Map<String, WindowState> ipStates = new ConcurrentHashMap<>();

    private static final int MAX_REQUESTS = 10;
    private static final long WINDOW_DURATION_MS = 60_000; // 1 Minute

    private static class WindowState {
        final AtomicLong windowStart;
        final AtomicInteger requestCount;

        WindowState(long start) {
            this.windowStart = new AtomicLong(start);
            this.requestCount = new AtomicInteger(0);
        }
    }

    /**
     * Prüft, ob eine Anfrage vom Client innerhalb des Zeitfensters erlaubt ist.
     * @param clientIp Die IP-Adresse des Clients
     * @return true wenn erlaubt, false wenn Rate Limit überschritten
     */
    public boolean isAllowed(String clientIp) {
        if (clientIp == null || clientIp.isEmpty()) {
            clientIp = "unknown";
        }

        long now = System.currentTimeMillis();
        WindowState state = ipStates.computeIfAbsent(clientIp, k -> new WindowState(now));

        long windowStart = state.windowStart.get();

        // Prüfen, ob das Zeitfenster abgelaufen ist
        if (now - windowStart >= WINDOW_DURATION_MS) {
            // Neues Fenster starten, Zähler resetten
            state.windowStart.set(now);
            state.requestCount.set(0);
        }

        // Zähler erhöhen
        int currentCount = state.requestCount.incrementAndGet();

        // Prüfen, ob Limit erreicht wurde
        return currentCount <= MAX_REQUESTS;
    }
}
