 */
@ResponseStatus(HttpStatus.FORBIDDEN)
public class SecureFetchException extends RuntimeException {

    public SecureFetchException(String message) {
        super(message);
    }

    public SecureFetchException(String message, Throwable cause) {
        super(message, cause);
    }
}
