"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidationService.java
package com.example.securefetch;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Dienst zur Validierung von URLs und Hosts.
 * Schützt vor SSRF und DNS Rebinding durch Whitelisting und IP-Checks.
 */
public class UrlValidationService {

    // Konfigurierbare Whitelist für erlaubte Domains
    // In einer Produktionsumgebung sollte dies aus einer sicheren Konfigurationsquelle geladen werden.
    private static final Set<String> ALLOWED_DOMAINS = new HashSet<>(Arrays.asList(
            "trusted-api.example.com",
            "data-provider.example.org"
    ));

    /**
     * Prüft, ob der Host erlaubt ist und ob die Auflösung zu einer sicheren IP führt.
     *
     * @param host Der vom Benutzer angegebene Host.
     * @throws SecureFetchException Wenn der Host nicht erlaubt ist oder eine private IP auflöst.
     */
    public void validateHost(String host) throws SecureFetchException {
        if (host == null || host.trim().isEmpty()) {
            throw new SecureFetchException("Host ist erforderlich.");
        }

        // 1. Normalisierung für flexible Vergleichbarkeit (CWE-180 Schutz)
        // Entfernt führende/trailing Punkte und macht klein, aber behält Subdomains bei.
        String normalizedHost = host.toLowerCase().replaceAll("^\\.+|\\.+$", "");

        // Entferne optional 'www.' für flexibleren Match innerhalb der Whitelist
        String checkHost = normalizedHost.startsWith("www.") ? normalizedHost.substring(4) : normalizedHost;

        // 2. Whitelist-Prüfung
        boolean isAllowed = false;
        for (String allowed : ALLOWED_DOMAINS) {
            if (checkHost.equals(allowed) || checkHost.endsWith("." + allowed)) {
                isAllowed = true;
                break;
            }
        }

        if (!isAllowed) {
            throw new SecureFetchException("Host '" + host + "' ist nicht in der Whitelist enthalten.");
        }

        // 3. DNS Auflösung und IP-Prüfung (Verhindert DNS Rebinding)
        try {
            InetAddress[] addresses = InetAddress.getAllByName(host);
            for (InetAddress addr : addresses) {
                if (isPrivateIp(addr)) {
                    throw new SecureFetchException("Ziel-IP (" + addr.getHostAddress() + ") ist privat/intern und nicht erlaubt.");
                }
            }
        } catch (UnknownHostException e) {
            throw new SecureFetchException("Host konnte nicht aufgelöst werden.", e);
        }
    }

    /**
     * Prüft, ob eine IP-Adresse im privaten Bereich liegt (RFC 1918, Loopback, Link-Local).
     *
     * @param address Die zu prüfende IP-Adresse.
     * @return True, wenn die Adresse privat ist.
     */
    private boolean isPrivateIp(InetAddress address) {
        byte[] addrBytes = address.getAddress();

        // Loopback (127.0.0.0/8)
        if (address.isLoopbackAddress()) return true;

        // Link Local (169.254.0.0/16)
        if (address.isLinkLocalAddress()) return true;

        // Site Local (Private IPv4)
        if (addrBytes.length == 4) {
            int firstByte = addrBytes[0] & 0xFF;
            int secondByte = addrBytes[1] & 0xFF;

            // 10.0.0.0/8
            if (firstByte == 10) return true;
            // 172.16.0.0/12
            if (firstByte == 172 && secondByte >= 16 && secondByte <= 31) return true;
            // 192.168.0.0/16
            if (firstByte == 192 && secondByte == 168) return true;
        }

        // IPv6 Loopback
        if (address.isAnyLocalAddress() || address.isLoopbackAddress()) return true;

        return false;
    }
}
