"}, {"type": "CODE_BLOCK", "language": "java", "content": "// HttpClientSecurityConfig.java
package com.example.securefetch;

import io.netty.handler.ssl.SslContext;
import io.netty.handler.ssl.SslContextBuilder;
import io.netty.handler.ssl.util.InsecureTrustManagerFactory;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import reactor.netty.http.client.HttpClient;

import javax.net.ssl.SSLException;
import java.security.cert.CertificateException;

/**
 * Konfiguration für den sicheren HTTP-Client.
 * Erzwingt TLS 1.2+, deaktiviert schwache Cipher Suites und deaktiviert Redirects.
 */
@Configuration
public class HttpClientSecurityConfig {

    @Bean
    public HttpClient secureHttpClient() {
        try {
            SslContext sslContext = SslContextBuilder.forClient()
                    .protocols("TLSv1.2", "TLSv1.3") // Nur starke Protokolle
                    .ciphers("TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384", 
                             "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
                             "TLS_AES_256_GCM_SHA384",
                             "TLS_AES_128_GCM_SHA256") // Nur GCM Ciphers
                    .build();

            return HttpClient.create()
                    .secure(spec -> spec.sslContext(sslContext))
                    .followRedirect(false); // Verhindert Redirect-basierte Angriffe
        } catch (SSLException e) {
            throw new RuntimeException("Fehler beim Erstellen des sicheren SSL-Kontexts", e);
        }
    }
}
