package com.example.securefetch;

import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;
import reactor.netty.http.client.HttpClient;
import reactor.netty.http.client.HttpClientResponse;

import java.nio.charset.StandardCharsets;

/**
 * Business-Logik für den externen Datenabruf.
 * Nutzt den konfigurierten sicheren Client.
 */
@Service
public class ExternalDataService {

    private final UrlValidationService urlValidationService;
    private final HttpClient httpClient;

    public ExternalDataService(UrlValidationService urlValidationService, HttpClient httpClient) {
        this.urlValidationService = urlValidationService;
        this.httpClient = httpClient;
    }

    /**
     * Ruft Daten von der angegebenen URL ab.
     *
     * @param host Der Host aus der Anfrage.
     * @return Mono mit dem FetchResponse.
     */
    public Mono<FetchResponse> fetchData(String host) {
        // 1. Sicherheitsprüfung durchführen
        urlValidationService.validateHost(host);

        String url = "https://" + host + "/api/data"; // Beispiel-Pfad

        return httpClient.get()
                .uri(url)
                .responseContent()
                .aggregate()
                .asString(StandardCharsets.UTF_8)
                .flatMap(body -> {
                    // Hier müsste normalerweise der Header-Statuscode und Content-Type extrahiert werden.
                    // Für dieses Beispiel simulieren wir eine erfolgreiche Antwortstruktur.
                    // In einer echten Implementierung würde man HttpClientResponse nutzen, um Headers zu lesen.
                    return Mono.just(new FetchResponse(200, "text/plain", body));
                })
                .onErrorResume(SecureFetchException.class, e -> Mono.error(e))
                .onErrorResume(Exception.class, e -> Mono.error(new SecureFetchException("Fehler beim Abruf der Daten: " + e.getMessage())));
    }
}
