"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FingerprintService.java
package com.example.security.fingerprint;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Service zur Berechnung des kryptografischen Hashes.
 * Kapselt die Logik zur Vermeidung von Information Leakage.
 */
@Service
public class FingerprintService {

    private static final Logger logger = LoggerFactory.getLogger(FingerprintService.class);
    private static final int MAX_INPUT_LENGTH = 1024; // Schutz vor DoS durch riesige Inputs

    /**
     * Generiert einen SHA-256 Hash für den gegebenen Wert.
     *
     * @param value Der zu hashende String.
     * @return Der Hex-kodierte Hash-String.
     * @throws FingerprintValidationException Wenn die Eingabe ungültig ist.
     */
    public String generateFingerprint(String value) throws FingerprintValidationException {
        // Validierung der Eingabe
        if (value == null) {
            throw new FingerprintValidationException("Der 'value' Parameter darf nicht null sein.");
        }

        if (value.length() > MAX_INPUT_LENGTH) {
            logger.warn("Eingabelänge überschreitet Maximum ({}) für Value.", value.length());
            throw new FingerprintValidationException("Der Wert ist zu lang.");
        }

        if (value.isEmpty()) {
            throw new FingerprintValidationException("Der Wert darf nicht leer sein.");
        }

        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(value.getBytes(StandardCharsets.UTF_8));

            // Konvertierung in Hex-String für stabile Ausgabe
            StringBuilder hexString = new StringBuilder(2 * hashBytes.length);
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Sollte theoretisch nie passieren, da SHA-256 Standard ist.
            // Logge sicherheitssensitiv, werfe aber keine Details raus.
            logger.error("Kryptografischer Algorithmus SHA-256 nicht gefunden. Systemzustand prüfen.", e);
            throw new FingerprintValidationException("Systemfehler bei der Hash-Berechnung.");
        }
    }
}
