package com.example.security.fingerprint;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST Controller für das Fingerprint-Endpoint.
 * Delegiert an den Service und gibt sichere Antworten zurück.
 */
@RestController
public class FingerprintController {

    private final FingerprintService fingerprintService;

    public FingerprintController(FingerprintService fingerprintService) {
        this.fingerprintService = fingerprintService;
    }

    /**
     * GET /fingerprint
     * Erwartet Query Parameter: value
     */
    @GetMapping("/fingerprint")
    public ResponseEntity<FingerprintResponseDTO> getFingerprint(@RequestParam("value") String value) {
        try {
            String hash = fingerprintService.generateFingerprint(value);
            FingerprintResponseDTO response = new FingerprintResponseDTO(hash);
            return ResponseEntity.ok(response);
        } catch (FingerprintValidationException e) {
            // Diese Exception wird vom GlobalExceptionHandler behandelt, 
            // damit keine Details an den Client gelangen.
            throw e;
        } catch (Exception e) {
            // Catch-all für unerwartete Fehler, ebenfalls abgefangen durch Handler
            throw e;
        }
    }
}
