"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.security.fingerprint;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.HashMap;
import java.util.Map;

/**
 * Globaler Exception Handler zur Sicherstellung von CERT Rule ERR01-J.
 * Verhindert Information Disclosure durch Fehlermeldungen (CWE-209).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger logger = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Behandelt benutzerdefinierte Validierungsfehler.
     * Gibt HTTP 400 zurück, ohne interne Details preiszugeben.
     */
    @ExceptionHandler(FingerprintValidationException.class)
    public ResponseEntity<Map<String, String>> handleValidationException(FingerprintValidationException ex) {
        // Internes Logging der Details für Admins
        logger.warn("Validierungsfehler: {}", ex.getMessage(), ex);

        Map<String, String> errorBody = new HashMap<>();
        errorBody.put("error", "Ungültiger Eingabeparameter");
        errorBody.put("message", "Bitte überprüfen Sie Ihre Anfrage.");

        return ResponseEntity.badRequest().body(errorBody);
    }

    /**
     * Behandelt alle anderen nicht gefangenen Exceptions.
     * Verhindert Leckage von Stack Traces oder internen Klassennamen.
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, String>> handleGenericException(Exception ex) {
        // Internes Logging der Details für Admins
        logger.error("Unbehandelte Exception im Fingerprint-Service", ex);

        Map<String, String> errorBody = new HashMap<>();
        errorBody.put("error", "Interner Server Fehler");
        errorBody.put("message", "Ein unerwarteter Fehler ist aufgetreten.");

        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(errorBody);
    }
}
