package com.example.secureapp.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

/**
 * Konfigurationsklasse für kryptographische Einstellungen.
 * Werte sollten aus Environment Variables oder einem sicheren Vault kommen, nicht aus dem Code.
 */
@Component
@ConfigurationProperties(prefix = "security.encryption")
public class EncryptionConfig {

    /**
     * Pfad zum Java KeyStore, der den Master-Key enthält.
     * Sollte außerhalb des Web-Roots liegen.
     */
    private String keyStorePath;

    /**
     * Alias des Master-Schlüssels im KeyStore.
     */
    private String masterKeyAlias;

    /**
     * Iterationen für die Schlüsselableitung (KDF).
     * Höhere Werte erhöhen die Sicherheit gegen Brute-Force, kosten aber Performance.
     */
    private int keyDerivationIterations = 100000;

    public String getKeyStorePath() {
        return keyStorePath;
    }

    public void setKeyStorePath(String keyStorePath) {
        this.keyStorePath = keyStorePath;
    }

    public String getMasterKeyAlias() {
        return masterKeyAlias;
    }

    public void setMasterKeyAlias(String masterKeyAlias) {
        this.masterKeyAlias = masterKeyAlias;
    }

    public int getKeyDerivationIterations() {
        return keyDerivationIterations;
    }

    public void setKeyDerivationIterations(int keyDerivationIterations) {
        this.keyDerivationIterations = keyDerivationIterations;
    }
}
