"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureCryptoProvider.java
package com.example.secureapp.service;

import com.example.secureapp.config.EncryptionConfig;
import com.example.secureapp.exception.UserIdValidationException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.Security;
import java.security.cert.CertificateException;
import java.security.KeyStore;
import java.security.KeyStoreException;
import java.security.NoSuchAlgorithmException;
import java.security.UnrecoverableKeyException;
import java.security.spec.AlgorithmParameterSpec;
import java.util.Arrays;
import java.util.Base64;

/**
 * Dienstklasse zur Handhabung aller kryptographischen Operationen.
 * Verwendet AES-GCM für sichere symmetrische Verschlüsselung.
 * Vermeidet das Schreiben eigener Krypto-Algorithmen (OWASP Guideline).
 */
@Service
public class SecureCryptoProvider {

    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";
    private static final int TAG_LENGTH_BIT = 128;
    private static final int IV_LENGTH_BYTE = 12; // 96 bits recommended for GCM
    private static final String HASH_ALGORITHM = "SHA-256";

    private final EncryptionConfig config;

    @Autowired
    public SecureCryptoProvider(EncryptionConfig config) {
        this.config = config;
    }

    /**
     * Lädt den Master-Key aus dem Java KeyStore.
     * Dies stellt sicher, dass der Root-Trust nicht im Code gehardcodet ist.
     */
    private SecretKey loadMasterKey() throws Exception {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        // Hinweis: In Produktion sollte das Passwort aus einem externen Secrets Manager kommen
        char[] password = System.getenv("KEYSTORE_PASSWORD").toCharArray(); 
        try (var inputStream = getClass().getClassLoader().getResourceAsStream(config.getKeyStorePath())) {
            if (inputStream == null) {
                throw new IllegalStateException("KeyStore file not found: " + config.getKeyStorePath());
            }
            keyStore.load(inputStream, password);
        } catch (CertificateException | NoSuchAlgorithmException | IOException e) {
            throw new RuntimeException("Failed to load KeyStore", e);
        }

        try {
            return (SecretKey) keyStore.getKey(config.getMasterKeyAlias(), password);
        } catch (UnrecoverableKeyException | KeyStoreException e) {
            throw new RuntimeException("Failed to retrieve Master Key", e);
        }
    }

    /**
     * Leitet einen benutzerspezifischen Schlüssel aus dem Master-Key und der User-ID ab.
     * Nutzt SHA-256 für Determinismus.
     * WARNUNG: Deterministische Schlüsselableitung kann bei schwachen Passwörtern anfällig sein.
     */
    private SecretKey deriveUserKey(SecretKey masterKey, String userId) throws Exception {
        MessageDigest digest = MessageDigest.getInstance(HASH_ALGORITHM);

        // Kombination aus Master-Key Bytes und User-ID für Determinismus
        byte[] combined = new byte[masterKey.getEncoded().length + userId.getBytes(StandardCharsets.UTF_8).length];
        System.arraycopy(masterKey.getEncoded(), 0, combined, 0, masterKey.getEncoded().length);
        System.arraycopy(userId.getBytes(StandardCharsets.UTF_8), 0, combined, masterKey.getEncoded().length, userId.getBytes(StandardCharsets.UTF_8).length);

        byte[] hashed = digest.digest(combined);
        // AES-256 Key Size
        return new SecretKeySpec(Arrays.copyOfRange(hashed, 0, 32), ALGORITHM);
    }

    /**
     * Generiert einen deterministischen IV basierend auf Plaintext und User-ID.
     * Dies erfüllt die Anforderung nach deterministischer Verschlüsselung.
     * Risiko: Gleicher Plaintext führt immer zum gleichen Chiffretext (Pattern Leakage).
     */
    private byte[] generateDeterministicIv(String plaintext, String userId) throws Exception {
        MessageDigest digest = MessageDigest.getInstance(HASH_ALGORITHM);
        byte[] input = (plaintext + userId).getBytes(StandardCharsets.UTF_8);
        byte[] hash = digest.digest(input);
        // Auf IV-Länge kürzen
        return Arrays.copyOf(hash, IV_LENGTH_BYTE);
    }

    /**
     * Verschlüsselt den Text mit AES-GCM.
     */
    public String encrypt(String plaintext, String userId) throws Exception {
        if (plaintext == null || plaintext.isEmpty()) {
            throw new IllegalArgumentException("Plaintext cannot be empty");
        }

        SecretKey masterKey = loadMasterKey();
        SecretKey userKey = deriveUserKey(masterKey, userId);

        // Deterministisches IV für gleiche Ergebnisse bei gleichem Input/User
        byte[] iv = generateDeterministicIv(plaintext, userId);

        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        AlgorithmParameterSpec paramSpec = new GCMParameterSpec(TAG_LENGTH_BIT, iv);
        cipher.init(Cipher.ENCRYPT_MODE, userKey, paramSpec);

        byte[] cipherText = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));

        // Concatenate IV and CipherText for storage/transmission
        byte[] result = new byte[iv.length + cipherText.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(cipherText, 0, result, iv.length, cipherText.length);

        return Base64.getEncoder().encodeToString(result);
    }
}
