package com.example.secureapp.service;

import com.example.secureapp.config.EncryptionConfig;
import com.example.secureapp.dto.EncryptRequest;
import com.example.secureapp.dto.EncryptResponse;
import com.example.secureapp.exception.UserIdValidationException;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Base64;
import java.util.regex.Pattern;

/**
 * Business-Logik-Schicht für die Notiz-Verschlüsselung.
 * Koordiniert Validierung und Aufruf des Crypto-Providers.
 */
@Service
public class NoteEncryptionService {

    private static final Pattern USER_ID_PATTERN = Pattern.compile("^[a-zA-Z0-9_-]{1,64}$");
    private final SecureCryptoProvider cryptoProvider;
    private final EncryptionConfig config;

    @Autowired
    public NoteEncryptionService(SecureCryptoProvider cryptoProvider, EncryptionConfig config) {
        this.cryptoProvider = cryptoProvider;
        this.config = config;
    }

    /**
     * Verifiziert die User-ID gegen ein Allowlist-RegEx.
     * Verhindert Injection (CWE-89), falls der Wert später in SQL verwendet wird.
     */
    private void validateUserId(String userId) {
        if (userId == null || !USER_ID_PATTERN.matcher(userId).matches()) {
            throw new UserIdValidationException("Invalid userId format. Allowed: alphanumeric, underscore, hyphen.");
        }
    }

    /**
     * Verarbeitet die Verschlüsselungsanfrage.
     */
    public EncryptResponse encryptNote(EncryptRequest request, String userId) {
        // Validierung der User-ID
        if (userId == null) {
            // Fallback auf System-User oder Fehler, je nach Policy. Hier werfen wir Exception.
            throw new UserIdValidationException("userId is required for deterministic encryption.");
        }
        validateUserId(userId);

        // Validierung des Textes
        if (request == null || request.getText() == null) {
            throw new IllegalArgumentException("Request text is required");
        }

        try {
            String encryptedPayload = cryptoProvider.encrypt(request.getText(), userId);

            // Extrahiere IV aus dem Payload (erste 12 Bytes sind IV, Rest ist CipherText)
            byte[] decoded = Base64.getDecoder().decode(encryptedPayload);
            byte[] iv = new byte[12];
            System.arraycopy(decoded, 0, iv, 0, 12);
            String ivBase64 = Base64.getEncoder().encodeToString(iv);

            return new EncryptResponse(encryptedPayload, userId, ivBase64);
        } catch (Exception e) {
            // Logge intern, aber gib keine Details an den Client weiter (Information Disclosure Prevention)
            // In Produktion: logger.error("Encryption failed", e);
            throw new RuntimeException("Encryption process failed", e);
        }
    }
}
