package com.example.secureapp.controller;

import com.example.secureapp.dto.EncryptRequest;
import com.example.secureapp.dto.EncryptResponse;
import com.example.secureapp.exception.UserIdValidationException;
import com.example.secureapp.service.NoteEncryptionService;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST Controller für die Notiz-Verschlüsselung.
 * Exponiert keinen internen Zustand und behandelt Fehler einheitlich.
 */
@RestController
@RequestMapping("/api/notes")
public class NoteEncryptionController {

    private final NoteEncryptionService encryptionService;

    public NoteEncryptionController(NoteEncryptionService encryptionService) {
        this.encryptionService = encryptionService;
    }

    /**
     * POST /api/notes/encrypt
     * Akzeptiert Text-Payload und optionalen userId Query Parameter.
     */
    @PostMapping("/encrypt")
    public ResponseEntity<EncryptResponse> encryptNote(
            @Valid @RequestBody EncryptRequest request,
            @RequestParam(required = false) String userId) {

        try {
            EncryptResponse response = encryptionService.encryptNote(request, userId);
            return ResponseEntity.ok(response);
        } catch (UserIdValidationException e) {
            // 400 Bad Request für Validierungsfehler
            return ResponseEntity.badRequest().body(null);
        } catch (IllegalArgumentException e) {
            // 400 Bad Request für fehlende Pflichtfelder
            return ResponseEntity.badRequest().body(null);
        } catch (Exception e) {
            // 500 Internal Server Error für unerwartete Fehler
            // Keine Stacktrace im Response zurückgeben (OWASP Top 10 A10)
            return ResponseEntity.internalServerError().build();
        }
    }
}
