package com.example.secureapi.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * DTO für den Incoming Partner Callback Request.
 * Enthält strenge Validierungsregeln, um XSS und ungültige Daten zu verhindern.
 */
public class PartnerCallbackRequest {

    @NotBlank(message = "orderId ist erforderlich")
    @Size(max = 64, message = "orderId darf nicht länger als 64 Zeichen sein")
    // Erlaubt nur alphanumerische Zeichen und Bindestriche, um SQL/XSS-Injektionen im Namen zu erschweren
    @Pattern(regexp = "^[a-zA-Z0-9-]+$", message = "orderId enthält ungültige Zeichen")
    private String orderId;

    @NotBlank(message = "status ist erforderlich")
    @Size(max = 50, message = "status darf nicht länger als 50 Zeichen sein")
    @Pattern(regexp = "^(SUCCESS|FAILURE|PENDING)$", message = "status muss SUCCESS, FAILURE oder PENDING sein")
    private String status;

    @NotNull(message = "amount ist erforderlich")
    private Double amount;

    // Getter und Setter
    public String getOrderId() { return orderId; }
    public void setOrderId(String orderId) { this.orderId = orderId; }

    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }

    public Double getAmount() { return amount; }
    public void setAmount(Double amount) { this.amount = amount; }
}
