package com.example.secureapi.repository;

import com.example.secureapi.entity.Order;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * Repository Interface für Datenbankzugriffe.
 * Nutzt JPA Prepared Statements automatisch.
 * Custom Query verwendet explizite Parameterbindung (:orderId), um CWE-89 zu verhindern.
 */
@Repository
public interface OrderRepository extends JpaRepository<Order, String> {

    /**
     * Findet eine Bestellung sicher nach ID.
     * JPA übersetzt dies in ein Prepared Statement.
     */
    Optional<Order> findByOrderId(@Param("id") String id);

    /**
     * Aktualisiert Status und Amount sicher.
     * Der Modifying Annotation sorgt dafür, dass JPA die Transaktion korrekt handhabt.
     * Der Query nutzt :orderId und :newStatus als gebundene Parameter.
     * Dies verhindert SQL Injection, da der Wert nie direkt in den Query-String eingefügt wird.
     */
    @Modifying(clearAutomatically = true)
    @Query("UPDATE Order o SET o.status = :newStatus, o.amount = :newAmount, o.updatedAt = CURRENT_TIMESTAMP WHERE o.orderId = :orderId")
    int updateOrderStatusAndAmount(
            @Param("orderId") String orderId,
            @Param("newStatus") String newStatus,
            @Param("newAmount") Double newAmount
    );
}
