package com.example.secureapi.service;

import com.example.secureapi.dto.OrderResponse;
import com.example.secureapi.dto.PartnerCallbackRequest;
import com.example.secureapi.entity.Order;
import com.example.secureapi.repository.OrderRepository;
import com.example.secureapi.exception.ValidationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;

/**
 * Service Layer für Geschäftslogik.
 * Kapselt die Datenbanklogik und validiert Eingaben vor der Persistenz.
 */
@Service
@Transactional
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    /**
     * Verarbeitet den Partner Callback.
     * Erstellt neue Orders oder aktualisiert bestehende.
     * Nutzt Parameterisierte Queries via Repository.
     */
    public OrderResponse processCallback(PartnerCallbackRequest request) {
        // Validierung der Logik (zusätzlich zur Bean Validation im Controller)
        if (request.getAmount() == null || request.getAmount() < 0) {
            throw new ValidationException("Ungültiger Betrag");
        }

        String orderId = request.getOrderId();
        String status = request.getStatus();
        Double amount = request.getAmount();

        // Suche existierende Order
        Order existingOrder = orderRepository.findByOrderId(orderId)
                .orElse(null);

        if (existingOrder != null) {
            // Update existierender Order
            // Hier wird die Methode updateOrderStatusAndAmount aufgerufen,
            // die intern einen parameterisierten JPQL-Query ausführt.
            int updatedRows = orderRepository.updateOrderStatusAndAmount(orderId, status, amount);

            if (updatedRows == 0) {
                // Fallback-Fall, falls ID gefunden wurde aber Update fehlgeschlagen ist
                throw new ValidationException("Update fehlgeschlagen");
            }
            return new OrderResponse(orderId, status, false);
        } else {
            // Neue Order erstellen
            Order newOrder = new Order(orderId, status, amount);
            orderRepository.save(newOrder);
            return new OrderResponse(orderId, status, true);
        }
    }
}
