"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.secureapi.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Spring Security Konfiguration.
 * 
 * Sicherheitsmaßnahmen:
 * 1. CSRF: Für API-zu-API Kommunikation (Stateless) oft deaktiviert, da Cookies nicht genutzt werden.
 *    Stattdessen wird Authentifizierung über Header (z.B. API-Key oder Bearer Token) erzwungen.
 *    Wenn Session-basiert, müsste csrf().enable() genutzt werden.
 * 2. CORS: Sollte streng konfiguriert werden (nur vertrauenswürdige Partner-Domains).
 * 3. Zugriffskontrolle: Alle API-Endpunkte müssen authentifiziert sein.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // Deaktiviert CSRF für reine API-Endpoints (kein Browser-Session Context)
            // Hinweis: Bei Browser-basierten Apps sollte CSRF aktiviert bleiben!
            .csrf(csrf -> csrf.disable()) 

            // Zustandslos (Stateless) für API Calls
            .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))

            // Autorisierung: Jeder Request muss authentifiziert sein
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/partners/callback/**").authenticated()
                .anyRequest().permitAll() // Beispiel: Health Checks dürfen offen sein
            )

            // Beispiel für API-Key Header Prüfung (Platzhalter für echte Implementierung)
            // In Produktion würde man hier einen Custom Filter für API Keys einfügen
            .headers(headers -> headers.frameOptions(frame -> frame.sameOrigin()))
            ;

        return http.build();
    }
}
