package com.example.settings.entity;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * Persistente Entität für die Anwendungseinstellungen.
 * Verwendet JPA für sicheren Datenbankzugriff ohne manuelle SQL-Konstruktion.
 */
@Entity
@Table(name = "application_settings")
public class ApplicationSettingsEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 50)
    private String defaultRole;

    @Column(precision = 19, scale = 2, nullable = false)
    private BigDecimal maxRefundAmount;

    @ElementCollection
    @CollectionTable(name = "application_settings_flags", joinColumns = @JoinColumn(name = "settings_id"))
    @Column(name = "flag_value")
    private boolean[] featureFlags;

    @Column(nullable = false, length = 100)
    private String supportEmail;

    private Boolean maintenanceMode;

    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    @Column(name = "updated_at")
    private LocalDateTime updatedAt;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
        updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    protected void onUpdate() {
        updatedAt = LocalDateTime.now();
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getDefaultRole() { return defaultRole; }
    public void setDefaultRole(String defaultRole) { this.defaultRole = defaultRole; }

    public BigDecimal getMaxRefundAmount() { return maxRefundAmount; }
    public void setMaxRefundAmount(BigDecimal maxRefundAmount) { this.maxRefundAmount = maxRefundAmount; }

    public boolean[] getFeatureFlags() { return featureFlags; }
    public void setFeatureFlags(boolean[] featureFlags) { this.featureFlags = featureFlags; }

    public String getSupportEmail() { return supportEmail; }
    public void setSupportEmail(String supportEmail) { this.supportEmail = supportEmail; }

    public Boolean getMaintenanceMode() { return maintenanceMode; }
    public void setMaintenanceMode(Boolean maintenanceMode) { this.maintenanceMode = maintenanceMode; }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }

    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}
