package com.example.settings.service;

import com.example.settings.dto.ApplicationSettingsRequest;
import com.example.settings.dto.ApplicationSettingsResponse;
import com.example.settings.entity.ApplicationSettingsEntity;
import com.example.settings.repository.ApplicationSettingsRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Arrays;

/**
 * Business-Logik für die Verwaltung der Anwendungseinstellungen.
 * Enthält die Merge-Logik und Audit-Logging.
 */
@Service
@Transactional
public class ApplicationSettingsService {

    private static final Logger logger = LoggerFactory.getLogger(ApplicationSettingsService.class);
    private final ApplicationSettingsRepository repository;

    @Autowired
    public ApplicationSettingsService(ApplicationSettingsRepository repository) {
        this.repository = repository;
    }

    /**
     * Aktualisiert oder initialisiert die Einstellungen.
     * Fehlt ein Wert im Request, bleibt der bestehende Wert erhalten (Merge-Verhalten).
     */
    public ApplicationSettingsResponse updateSettings(ApplicationSettingsRequest request) {
        ApplicationSettingsEntity existingSettings = repository.findFirstByOrderByUpdatedAtDesc().orElse(null);

        // Initialisierung oder Update
        if (existingSettings == null) {
            existingSettings = new ApplicationSettingsEntity();
        }

        // Sicherstellen, dass sensible Felder nicht leer sind, falls sie bereits existieren
        if (request.getDefaultRole() != null && !request.getDefaultRole().isEmpty()) {
            existingSettings.setDefaultRole(request.getDefaultRole());
        }

        if (request.getMaxRefundAmount() != null) {
            existingSettings.setMaxRefundAmount(request.getMaxRefundAmount());
        }

        if (request.getFeatureFlags() != null) {
            existingSettings.setFeatureFlags(Arrays.copyOf(request.getFeatureFlags(), request.getFeatureFlags().length));
        }

        if (request.getSupportEmail() != null && !request.getSupportEmail().isEmpty()) {
            existingSettings.setSupportEmail(request.getSupportEmail());
        }

        if (request.getMaintenanceMode() != null) {
            existingSettings.setMaintenanceMode(request.getMaintenanceMode());
        }

        repository.save(existingSettings);

        // Audit-Logging: Protokollierung der Änderung (ohne sensible Details im Log)
        logger.info("Application settings updated by authorized user. ID: {}", existingSettings.getId());

        return mapToResponse(existingSettings);
    }

    private ApplicationSettingsResponse mapToResponse(ApplicationSettingsEntity entity) {
        return new ApplicationSettingsResponse(
                entity.getDefaultRole(),
                entity.getMaxRefundAmount(),
                entity.getFeatureFlags(),
                entity.getSupportEmail(),
                entity.getMaintenanceMode()
        );
    }
}
