package com.example.settings.controller;

import com.example.settings.dto.ApplicationSettingsRequest;
import com.example.settings.dto.ApplicationSettingsResponse;
import com.example.settings.service.ApplicationSettingsService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

/**
 * REST Controller für die Verwaltung der Anwendungseinstellungen.
 * Schützt den Endpunkt durch Authorization und Content-Type Enforcement.
 */
@RestController
@RequestMapping("/api/v1/settings")
public class ApplicationSettingsController {

    private final ApplicationSettingsService service;

    public ApplicationSettingsController(ApplicationSettingsService service) {
        this.service = service;
    }

    /**
     * POST / PUT Endpoint zum Aktualisieren der Einstellungen.
     * Nur für Administratoren zugänglich (@PreAuthorize).
     * Akzeptiert nur JSON.
     */
    @PostMapping(consumes = "application/json", produces = "application/json")
    @PutMapping(consumes = "application/json", produces = "application/json")
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<ApplicationSettingsResponse> updateSettings(@Valid @RequestBody ApplicationSettingsRequest request) {
        try {
            ApplicationSettingsResponse response = service.updateSettings(request);
            return ResponseEntity.ok(response);
        } catch (IllegalArgumentException e) {
            // Sicherheit: Keine internen Details zurückgeben
            return ResponseEntity.badRequest().build();
        }
    }

    /**
     * GET Endpoint zum Abrufen der aktuellen Einstellungen.
     * Auch hier ist Authentifizierung erforderlich.
     */
    @GetMapping(produces = "application/json")
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<ApplicationSettingsResponse> getSettings() {
        // Hier müsste die Logik zum Abrufen hinzugefügt werden, 
        // da der Service aktuell nur 'update' hat. Für dieses Beispiel simulieren wir dies.
        return ResponseEntity.ok(new ApplicationSettingsResponse());
    }
}
