package com.example.securecart;

import com.example.securecart.dto.CartRequestDTO;
import com.example.securecart.dto.CartResponseDTO;
import com.example.securecart.service.CartService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Base64;
import java.util.Map;

@RestController
@RequestMapping("/api/cart")
public class CartController {

    private static final Logger logger = LoggerFactory.getLogger(CartController.class);
    private final CartService cartService;

    public CartController(CartService cartService) {
        this.cartService = cartService;
    }

    /**
     * POST /api/cart/load
     * Akzeptiert einen Base64-kodierten JSON-String, der den Warenkorb darstellt.
     */
    @PostMapping("/load")
    public ResponseEntity<Map<String, Object>> loadCart(@RequestBody String encodedCart) {
        try {
            // 1. Sicheres Decodieren von Base64
            byte[] decodedBytes = Base64.getDecoder().decode(encodedCart);

            // 2. Konvertierung in String (UTF-8) und Validierung auf leere Daten
            String jsonString = new String(decodedBytes, java.nio.charset.StandardCharsets.UTF_8);
            if (jsonString == null || jsonString.trim().isEmpty()) {
                throw new IllegalArgumentException("Leerer Warenkorb");
            }

            // 3. Deserialisierung unter Verwendung des sicheren ObjectMapper aus der Konfiguration
            // Wir mappen direkt auf das Request DTO, um Typosicherheit zu gewährleisten
            CartRequestDTO requestDTO = cartService.deserializeCart(jsonString);

            // 4. Geschäftslogik und Berechnung
            CartResponseDTO responseDTO = cartService.processCart(requestDTO);

            // 5. Rückgabe des sicheren Response DTOs
            return ResponseEntity.ok(responseDTO.toMap());

        } catch (IllegalArgumentException e) {
            // Logge den Fehler, aber gib keine Details an den Client weiter
            logger.warn("Ungültige Anfrage: {}", e.getMessage());
            return ResponseEntity.badRequest().body(Map.of("error", "Ungültiges Format"));
        } catch (Exception e) {
            // Interne Fehler werden hier abgefangen, um CWE-209 zu vermeiden
            logger.error("Interner Fehler beim Laden des Warenkorbs", e);
            return ResponseEntity.internalServerError().body(Map.of("error", "Serverfehler"));
        }
    }
}
