"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartRequestDTO.java
package com.example.securecart.dto;

import java.io.Serializable;
import java.util.List;

/**
 * Data Transfer Object für die Anfrage.
 * Immutable Design Pattern wird durch fehlende Setter und private final Felder erzwungen.
 * Dies erfüllt CERT SER06-J Anforderungen indirekt, da Mutation nach Konstruktion unmöglich ist.
 */
public class CartRequestDTO implements Serializable {

    private static final long serialVersionUID = 1L;

    private final List<CartItemDTO> items;

    public CartRequestDTO(List<CartItemDTO> items) {
        // Defensive Kopie der Liste, um Referenz-Manipulation zu verhindern
        this.items = items != null ? new java.util.ArrayList<>(items) : new java.util.ArrayList<>();
    }

    public List<CartItemDTO> getItems() {
        // Auch Getter geben eine defensive Kopie zurück, falls die interne Liste später geändert würde
        return new java.util.ArrayList<>(this.items);
    }
}
