"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartService.java
package com.example.securecart.service;

import com.example.securecart.dto.CartRequestDTO;
import com.example.securecart.dto.CartResponseDTO;
import com.example.securecart.dto.CartItemDTO;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;

import java.util.List;
import java.util.stream.Collectors;

@Service
public class CartService {

    private final ObjectMapper objectMapper;

    public CartService(ObjectMapper objectMapper) {
        this.objectMapper = objectMapper;
    }

    /**
     * Deserialisiert den JSON-String sicher.
     * Da ObjectMapper bereits in SecureJacksonConfig eingeschränkt wurde,
     * ist dies sicherer als direkte Java-Serialisierung.
     */
    public CartRequestDTO deserializeCart(String jsonString) throws JsonProcessingException {
        // Mapping auf das spezifische DTO statt roher Klassen
        return objectMapper.readValue(jsonString, CartRequestDTO.class);
    }

    /**
     * Validiert und verarbeitet den Warenkorb.
     * Hier werden Invarianten geprüft (CERT SER07-J).
     */
    public CartResponseDTO processCart(CartRequestDTO request) {
        List<CartItemDTO> items = request.getItems();

        if (items == null || items.isEmpty()) {
            throw new IllegalArgumentException("Warenkorb darf nicht leer sein");
        }

        double totalSum = 0.0;

        for (CartItemDTO item : items) {
            // Validierung einzelner Items (Preise müssen positiv sein)
            if (item.getPrice() < 0) {
                throw new IllegalArgumentException("Preis kann nicht negativ sein");
            }
            if (item.getName() == null || item.getName().trim().isEmpty()) {
                throw new IllegalArgumentException("Name darf nicht leer sein");
            }
            totalSum += item.getPrice();
        }

        // Sicherstellen, dass die Gesamtsumme nicht ins Unendliche geht (Overflow-Schutz)
        if (Double.isInfinite(totalSum)) {
            throw new IllegalArgumentException("Berechnungsfehler bei der Summenbildung");
        }

        return new CartResponseDTO(items, totalSum);
    }
}
