package com.example.securecart.config;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Konfiguration des Jackson ObjectMapper für maximale Sicherheit.
 * Verhindert CWE-502 Angriffe durch Deaktivierung von Polymorphie-Typen.
 */
@Configuration
public class SecureJacksonConfig {

    @Bean
    public ObjectMapper secureObjectMapper() {
        ObjectMapper mapper = new ObjectMapper();

        // 1. Deaktiviere Default Typing (wichtigster Schritt gegen CWE-502)
        // Ohne diese Einstellung könnte Jackson beliebige Klassen instanziieren
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        mapper.disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
        mapper.configure(com.fasterxml.jackson.databind.MapperFeature.DEFAULT_VIEW_INCLUSION, false);

        // 2. Registriere Module für moderne Datentypen
        mapper.registerModule(new JavaTimeModule());

        // 3. Verhindere das Lesen von unbekannten Eigenschaften, um Inkonsistenzen zu vermeiden
        // (Optional, je nach Anforderung, hier aktiviert für strikte Validierung)
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, true);

        return mapper;
    }
}
