"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.securecart.exception;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.Map;

/**
 * Zentrale Exception-Behandlung.
 * Verhindert CWE-209 (Exception Information Disclosure).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger logger = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<Map<String, Object>> handleIllegalArgument(IllegalArgumentException e) {
        // Logge den vollen Stacktrace intern
        logger.error("Validierungsfehler: {}", e.getMessage(), e);
        return ResponseEntity.badRequest().body(Map.of("error", "Ungültige Eingabedaten"));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> handleGenericException(Exception e) {
        // Logge den vollen Stacktrace intern
        logger.error("Unbekannter interner Fehler", e);
        // Gib nur eine generische Nachricht an den Client
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("error", "Ein interner Fehler ist aufgetreten"));
    }
}
