package com.example.secureapp;

/**
 * Laufzeitexception, die geworfen wird, wenn eine URL-Validierung fehlschlägt.
 * Wird verwendet, um ungültige Redirect-Ziele sicher abzufangen und zu melden.
 */
public class InvalidRedirectUrlException extends RuntimeException {

    private final String attemptedUrl;

    public InvalidRedirectUrlException(String message, String attemptedUrl) {
        super(message);
        this.attemptedUrl = attemptedUrl;
    }

    public String getAttemptedUrl() {
        return attemptedUrl;
    }
}
