"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectProperties.java
package com.example.secureapp;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Konfiguration für die Redirect-Einstellungen.
 * Liest die erlaubten Domains aus der application.properties (oder environment variables).
 * Beispiel Konfiguration: app.redirect.allowed-hosts=example.com,mysite.org
 */
@Component
@ConfigurationProperties(prefix = "app.redirect")
public class RedirectProperties {

    /**
     * Liste der erlaubten Hostnamen für Redirects.
     * Diese Liste sollte streng verwaltet werden.
     */
    private List<String> allowedHosts = new ArrayList<>();

    /**
     * Standard-URL, falls kein 'url' Parameter übergeben wurde.
     */
    private String defaultUrl = "/home";

    public List<String> getAllowedHosts() {
        // Defensive Kopie zurückgeben, damit der Aufrufer die Liste nicht manipulieren kann
        return Collections.unmodifiableList(new ArrayList<>(allowedHosts));
    }

    public void setAllowedHosts(List<String> allowedHosts) {
        this.allowedHosts = allowedHosts;
    }

    public String getDefaultUrl() {
        return defaultUrl;
    }

    public void setDefaultUrl(String defaultUrl) {
        this.defaultUrl = defaultUrl;
    }
}
