"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidator.java
package com.example.secureapp;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.List;

/**
 * Statische Validierungslogik für URLs.
 * Prüft Schema und Host gegen eine Whitelist.
 */
@Component
public class UrlValidator {

    private final RedirectProperties properties;

    @Autowired
    public UrlValidator(RedirectProperties properties) {
        this.properties = properties;
    }

    /**
     * Validiert eine URL basierend auf Schema und Host-Whitelist.
     *
     * @param urlString Die vom Benutzer bereitgestellte URL.
     * @return true, wenn die URL sicher ist.
     * @throws InvalidRedirectUrlException Wenn die URL nicht den Sicherheitsrichtlinien entspricht.
     */
    public boolean isValid(String urlString) {
        if (urlString == null || urlString.trim().isEmpty()) {
            return false;
        }

        try {
            URI uri = new URI(urlString);

            // 1. Schema-Prüfung: Nur http und https erlauben
            // Verhindert javascript:, data:, file:, gopher: etc.
            String scheme = uri.getScheme();
            if (scheme == null || (!scheme.equalsIgnoreCase("http") && !scheme.equalsIgnoreCase("https"))) {
                throw new InvalidRedirectUrlException("Nur http und https Schemata sind erlaubt.", urlString);
            }

            // 2. Host-Prüfung: Whitelist-Ansatz
            String host = uri.getHost();
            if (host == null || host.isEmpty()) {
                throw new InvalidRedirectUrlException("Keine gültige Host-Information gefunden.", urlString);
            }

            // Normalisierung des Hosts (kleinschreibung)
            String normalizedHost = host.toLowerCase();

            List<String> allowedHosts = properties.getAllowedHosts();
            boolean isAllowed = false;

            for (String allowed : allowedHosts) {
                if (normalizedHost.equals(allowed.toLowerCase())) {
                    isAllowed = true;
                    break;
                }
                // Optional: Subdomains erlauben (z.B. *.example.com)
                // Hier strikt auf exakte Übereinstimmung gesetzt, um Enumeration zu vermeiden.
            }

            if (!isAllowed) {
                throw new InvalidRedirectUrlException("Ziel-Host nicht in der Whitelist enthalten.", urlString);
            }

            return true;

        } catch (URISyntaxException e) {
            throw new InvalidRedirectUrlException("Ungültiges URL-Format.", urlString);
        }
    }
}
