"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectService.java
package com.example.secureapp;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

/**
 * Dienstklasse zur Orchestrierung der Redirect-Logik.
 * Kapselt Validierung und Logging.
 */
@Service
public class RedirectService {

    private static final Logger logger = LoggerFactory.getLogger(RedirectService.class);

    private final UrlValidator urlValidator;
    private final RedirectProperties properties;

    @Autowired
    public RedirectService(UrlValidator urlValidator, RedirectProperties properties) {
        this.urlValidator = urlValidator;
        this.properties = properties;
    }

    /**
     * Verarbeitet die Redirect-Anfrage.
     *
     * @param userProvidedUrl Die vom Client angegebene URL.
     * @return Die sichere Ziel-URL (inklusive Schema).
     * @throws InvalidRedirectUrlException Wenn die URL nicht validiert werden konnte.
     */
    public String processRedirect(String userProvidedUrl) {
        // Audit-Logging: Protokollieren des Versuchs unabhängig vom Erfolg
        logger.info("Redirect request received. Target: {}", 
                userProvidedUrl != null ? userProvidedUrl : "null");

        if (userProvidedUrl == null || userProvidedUrl.trim().isEmpty()) {
            // Kein Parameter vorhanden -> Weiterleitung zur Startseite
            logger.debug("No URL provided. Redirecting to default.");
            return properties.getDefaultUrl();
        }

        try {
            // Strikte Validierung durchführen
            if (urlValidator.isValid(userProvidedUrl)) {
                logger.info("Redirect validated successfully to: {}", userProvidedUrl);
                return userProvidedUrl;
            } else {
                // Sollte theoretisch nie passieren, da isValid Exception wirft, aber als Fallback
                logger.warn("Redirect validation failed silently for: {}", userProvidedUrl);
                return properties.getDefaultUrl();
            }
        } catch (InvalidRedirectUrlException e) {
            // Kritischer Fehler: Böser Versuch erkannt
            logger.error("SECURITY ALERT: Invalid redirect attempt blocked. Attempted URL: {}", 
                    e.getAttemptedUrl(), e);
            throw e;
        }
    }
}
