"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GoController.java
package com.example.secureapp;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Controller für den sicheren Redirect-Endpoint.
 * Endpoint: GET /go?url=<target_url>
 */
@RestController
public class GoController {

    private final RedirectService redirectService;

    @Autowired
    public GoController(RedirectService redirectService) {
        this.redirectService = redirectService;
    }

    /**
     * Sichere Redirect-Endpunkt.
     *
     * @param url Der Ziel-URL-Parameter.
     * @param response Das HttpServletResponse Objekt für manuelle Steuerung (optional).
     * @return ResponseEntity mit Statuscode 302 Found und Location Header.
     * @throws InvalidRedirectUrlException Falls die URL nicht sicher ist.
     */
    @GetMapping("/go")
    public ResponseEntity<?> goTo(@RequestParam(required = false) String url, 
                                  HttpServletResponse response) {

        try {
            // 1. Validierung und Bereinigung der URL im Service
            String safeTargetUrl = redirectService.processRedirect(url);

            // 2. Sicherstellen, dass die URL absolut ist für externe Redirects
            // Wenn safeTargetUrl ein relativer Pfad ist (z.B. /home), muss er zum absoluten Pfad gemacht werden
            if (!safeTargetUrl.startsWith("http://") && !safeTargetUrl.startsWith("https://")) {
                // Interne Weiterleitung innerhalb der App
                return ResponseEntity.status(HttpStatus.FOUND)
                        .location(new java.net.URI(safeTargetUrl))
                        .build();
            } else {
                // Externe Weiterleitung
                return ResponseEntity.status(HttpStatus.FOUND)
                        .location(new java.net.URI(safeTargetUrl))
                        .build();
            }

        } catch (InvalidRedirectUrlException e) {
            // Sicherheit: Bei ungültiger URL nicht weiterleiten, sondern Fehlerseite oder Home
            // Wir werfen hier die Exception, damit GlobalExceptionHandler sie fängt, 
            // oder wir leiten sicher um. Hier entscheiden wir uns für eine sichere Umleitung auf Home.
            // Alternativ könnte man auch 400 Bad Request zurückgeben.
            // Für UX oft besser: Auf Startseite landen lassen, aber im Log steht der Angriff.
            return ResponseEntity.status(HttpStatus.FOUND)
                    .location(new java.net.URI("/home"))
                    .build();
        } catch (Exception e) {
            // Generic Fallback
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Ein interner Fehler ist aufgetreten.");
        }
    }
}
