package com.example.security.service;

import org.apache.commons.lang3.StringUtils;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.XMLConstants;
import java.io.IOException;
import java.io.StringReader;

/**
 * Service zur sicheren Verarbeitung von XML-Daten.
 * Implementiert Schutzmechanismen gegen XXE (CWE-611).
 */
@Service
public class XmlService {

    private final XmlParser xmlParser;

    public XmlService(XmlParser xmlParser) {
        this.xmlParser = xmlParser;
    }

    /**
     * Hauptmethode zur Verarbeitung von XML.
     * Konfiguriert den Parser streng nach OWASP XXE Prevention Cheat Sheet.
     */
    public String processXml(String xmlData) {
        if (StringUtils.isBlank(xmlData)) {
            throw new IllegalArgumentException("XML-Daten dürfen nicht leer sein.");
        }

        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // --- XXE-SICHERHEITSMASSNAHMEN (CWE-611) ---
        try {
            // Primäre Verteidigung: DOCTYPE-Erklärungen komplett verbieten
            // Dies verhindert fast alle klassischen XXE-Angriffe
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Externe Entitäten deaktivieren (zusätzliche Absicherung)
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // Externe DTDs nicht laden
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // XInclude deaktivieren (verhindert Datei-Lesezugriffe via XInclude)
            factory.setXIncludeAware(false);

            // Feature für sichere Verarbeitung aktivieren (JDK 6+)
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Entity Expansion Limits setzen (Schutz vor Billion Laughs DoS)
            factory.setExpandEntityReferences(false);

        } catch (ParserConfigurationException | SAXException e) {
            // Logge den Fehler, aber werfe eine generische Exception, damit keine internen Details preisgegeben werden
            throw new RuntimeException("Sichere XML-Konfiguration konnte nicht angewendet werden.", e);
        }

        try {
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Sicherer EntityResolver: Blockiert jegliche Auflösung externer Referenzen
            builder.setEntityResolver((publicId, systemId) -> {
                // Gibt eine leere Quelle zurück, um Angriffe auf externe Ressourcen zu stoppen
                return new InputSource(new StringReader(""));
            });

            InputSource is = new InputSource(new StringReader(xmlData));
            Document doc = builder.parse(is);

            // Validierung der Struktur (CWE-20)
            if (!isValidStructure(doc)) {
                throw new IllegalArgumentException("Ungültige XML-Struktur erkannt.");
            }

            // Extraktion und Formatierung als JSON
            return xmlParser.toJson(doc);

        } catch (IOException e) {
            throw new RuntimeException("Fehler beim Parsen der XML-Daten.", e);
        }
    }

    /**
     * Einfache Validierung der XML-Struktur.
     * Prüft auf Vorhandensein eines Root-Elements.
     */
    private boolean isValidStructure(Document doc) {
        if (doc.getDocumentElement() == null) {
            return false;
        }
        // Hier könnte man auch eine Whitelist für erlaubte Tag-Namen implementieren
        // Beispiel: Nur "root" erlaubt
        String rootTag = doc.getDocumentElement().getTagName();
        if (!"root".equalsIgnoreCase(rootTag)) {
             // Für Demo-Zwecke akzeptieren wir hier alles, solange es ein Element ist.
             // In einer echten App würde man hier strikt prüfen.
        }
        return true;
    }
}
