"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlParser.java
package com.example.security.parser;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/**
 * Hilfsklasse zur Umwandlung von XML-Dokumenten in JSON-Strings.
 * Nutzt einfache DOM-Traversierung ohne externe Abhängigkeiten für die Darstellung.
 */
public class XmlParser {

    /**
     * Wandelt ein DOM-Dokument in ein vereinfachtes JSON-Format um.
     * 
     * @param doc Das geparste XML-Dokument
     * @return JSON-String Repräsentation
     */
    public String toJson(Document doc) {
        StringBuilder json = new StringBuilder("{\n");
        Element root = doc.getDocumentElement();
        json.append("  \"tag\": \"").append(escapeJson(root.getTagName())).append("\",\n");
        json.append("  \"attributes\": {\n");

        // Attribute verarbeiten
        boolean firstAttr = true;
        for (int i = 0; i < root.getAttributes().getLength(); i++) {
            if (!firstAttr) json.append(",\n");
            String key = escapeJson(root.getAttributes().item(i).getNodeName());
            String value = escapeJson(root.getAttributes().item(i).getNodeValue());
            json.append("    \"").append(key).append("\": \"").append(value).append("\"");
            firstAttr = false;
        }
        json.append("\n  },\n");

        // Textinhalt verarbeiten
        NodeList childNodes = root.getChildNodes();
        StringBuilder textContent = new StringBuilder();
        for (int i = 0; i < childNodes.getLength(); i++) {
            if (childNodes.item(i).getNodeType() == 3) { // TEXT_NODE
                textContent.append(childNodes.item(i).getNodeValue());
            }
        }
        json.append("  \"content\": \"").append(escapeJson(textContent.toString().trim())).append("\"\n");
        json.append("}");

        return json.toString();
    }

    /**
     * Escapet spezielle Zeichen für JSON-Strings.
     */
    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }
}
