"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlSecurityFilter.java
package com.example.security.filter;

import org.springframework.stereotype.Component;

import javax.servlet.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Servlet-Filter zur Validierung von HTTP-Headern und Content-Type.
 * Verhindert Missbrauch des Endpoints durch falsche Content-Typen.
 */
@Component
public class XmlSecurityFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {

        if (!(request instanceof HttpServletRequest) || !(response instanceof HttpServletResponse)) {
            chain.doFilter(request, response);
            return;
        }

        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Validierung des Content-Type Headers
        String contentType = httpRequest.getContentType();
        if (contentType == null || !contentType.contains("application/xml")) {
            httpResponse.sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE, 
                "Nur application/xml wird unterstützt.");
            return;
        }

        // Optional: Header-Größe begrenzen, um DoS zu verhindern
        // In Production sollte dies über Nginx/Apache oder Application Properties erfolgen

        chain.doFilter(request, response);
    }
}
