package com.example.security.config;

import com.example.security.filter.XmlSecurityFilter;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Spring-Konfiguration für Sicherheitsfilter.
 */
@Configuration
public class SecurityConfig {

    /**
     * Registriert den XmlSecurityFilter für den XML-Endpoint.
     */
    @Bean
    public FilterRegistrationBean<XmlSecurityFilter> xmlSecurityFilter() {
        FilterRegistrationBean<XmlSecurityFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(new XmlSecurityFilter());
        // Beschränkung auf den spezifischen Pfad
        registration.addUrlPatterns("/api/xml/*");
        registration.setName("xmlSecurityFilter");
        registration.setOrder(1); // Hohe Priorität
        return registration;
    }
}
