package com.example.security;

import com.example.dto.Customer;
import com.example.service.CustomerService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import javax.servlet.http.HttpServletRequest;
import java.util.List;

/**
 * REST Controller für Customer-Abfragen mit XXE-Schutz und Authentifizierung.
 * 
 * Sicherheitsmaßnahmen:
 * - HTTP Basic Authentication über Spring Security
 * - Input-Validierung gegen XXE-Injektion
 * - Keine direkten Datenbankzugriffe (vermeidet SQL Injection)
 */
@RestController
public class CustomerController {

    private final CustomerService customerService;

    @Autowired
    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    /**
     * Sucht einen Kunden nach Name und gibt JSON zurück.
     * 
     * @param customerName Der zu suchende Kundenname
     * @param httpRequest  Für Basic Auth Header
     * @return Customer-Daten als JSON oder Fehlermeldung
     */
    @GetMapping("/api/customers")
    public ResponseEntity<?> searchCustomer(
            @RequestParam String customerName,
            HttpServletRequest httpRequest) {

        // Input-Validierung: Nur alphanumerische Zeichen und Leerzeichen erlauben
        if (!isValidCustomerName(customerName)) {
            return ResponseEntity.badRequest()
                    .body("Ungültiger Kundenname. Nur Buchstaben, Zahlen und Leerzeichen erlaubt.");
        }

        try {
            List<Customer> results = customerService.findCustomersByName(customerName);

            if (results.isEmpty()) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND)
                        .body("Keine Kunden gefunden.");
            }

            return ResponseEntity.ok(results);
        } catch (XmlParsingException e) {
            // Logge den Fehler sicher (nicht im Response ausgeben)
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Interner Serverfehler bei der Verarbeitung.");
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Unerwarteter Fehler.");
        }
    }

    /**
     * Whitelist-Validierung für Kundennamen.
     * Verhindert Injection-Angriffe durch strikte Eingabeprüfung.
     * 
     * @param name Zu prüfender Name
     * @return true wenn gültig, sonst false
     */
    private boolean isValidCustomerName(String name) {
        if (name == null || name.trim().isEmpty()) {
            return false;
        }

        // Nur alphanumerische Zeichen, Leerzeichen und Bindestriche erlauben
        // Dies verhindert SQL-Injection, XXE-Payloads und andere Injektionen
        return name.matches("^[a-zA-Z0-9\\s\\-]+$");
    }
}
