package com.example.service;

import com.example.dto.Customer;
import com.example.parser.XmlParserConfig;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.validation.Schema;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Service für XML-basierte Kundenabfragen mit XXE-Schutz.
 * 
 * Sicherheitsmaßnahmen:
 * - Dokumentenparser mit disallow-doctype-decl konfiguriert
 * - XSD-Validierung gegen Schema-Verletzungen
 * - Secure Processing Mode aktiviert
 */
@Service
public class CustomerService {

    private final XmlParserConfig xmlParserConfig;

    @Autowired
    public CustomerService(XmlParserConfig xmlParserConfig) {
        this.xmlParserConfig = xmlParserConfig;
    }

    /**
     * Sucht Kunden im XML-File nach Namen.
     * 
     * @param customerName Der gesuchte Name
     * @return Liste gefundener Kunden
     * @throws XmlParsingException Bei Parser-Fehlern
     */
    public List<Customer> findCustomersByName(String customerName) throws XmlParsingException {
        // XML-Datei laden
        ClassPathResource resource = new ClassPathResource("customers.xml");
        String xmlContent = readFileToString(resource);

        // XML parsen mit sicherem Parser
        Document document = parseXmlSecurely(xmlContent);

        // XPath-ähnliche Suche im DOM
        NodeList customerNodes = document.getElementsByTagName("customer");
        List<Customer> results = new ArrayList<>();

        for (int i = 0; i < customerNodes.getLength(); i++) {
            var node = customerNodes.item(i);
            Customer customer = extractCustomerFromNode(node);

            if (customer != null && matchesSearchTerm(customer.getName(), customerName)) {
                results.add(customer);
            }
        }

        return results;
    }

    /**
     * Lädt Dateiinhalt als String.
     */
    private String readFileToString(ClassPathResource resource) throws XmlParsingException {
        try {
            StringBuilder content = new StringBuilder();
            byte[] bytes = resource.getInputStream().readAllBytes();
            content.append(new String(bytes));
            return content.toString();
        } catch (Exception e) {
            throw new XmlParsingException("Fehler beim Laden der XML-Datei", e);
        }
    }

    /**
     * Parsen mit XXE-geschütztem DocumentBuilderFactory.
     * 
     * WICHTIG: Alle XXE-Sicherheitsfeatures werden hier konfiguriert.
     */
    private Document parseXmlSecurely(String xmlContent) throws XmlParsingException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // XXE-Schutz: Alle externen Entitäten und DTDs deaktivieren
        try {
            // PRIMARY DEFENSE: DOCTYPE komplett verbieten
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // Externe General Entities verhindern
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // Externe Parameter Entities verhindern
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // Externe DTDs nicht laden
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // XInclude deaktivieren (verhindert file:// Zugriffe)
            factory.setXIncludeAware(false);

            // Entity Expansion begrenzen (Billion Laughs DoS Schutz)
            factory.setExpandEntityReferences(false);

            // Secure Processing Mode aktivieren
            factory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // XSD-Validierung konfigurieren
            Schema schema = loadSchema();
            factory.setSchema(schema);

        } catch (Exception e) {
            throw new XmlParsingException("Fehler bei der Parser-Konfiguration", e);
        }

        try {
            DocumentBuilder builder = factory.newDocumentBuilder();
            // EntityResolver setzen um externe Ressourcen komplett zu blockieren
            builder.setEntityResolver((publicId, systemId) -> new org.xml.sax.InputSource(new StringReader("")));

            return builder.parse(new InputSource(new StringReader(xmlContent)));
        } catch (Exception e) {
            throw new XmlParsingException("Fehler beim Parsen der XML-Daten", e);
        }
    }

    /**
     * Lädt das XSD-Schema für die Validierung.
     */
    private Schema loadSchema() throws XmlParsingException {
        try {
            javax.xml.validation.SchemaFactory schemaFactory = 
                javax.xml.validation.SchemaFactory.newInstance(
                    javax.xml.XMLConstants.W3C_XML_SCHEMA_NS_URI);

            // Externe Schemas nicht laden
            schemaFactory.setProperty(
                javax.xml.XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
            schemaFactory.setProperty(
                javax.xml.XMLConstants.ACCESS_EXTERNAL_DTD, "");

            ClassPathResource schemaResource = new ClassPathResource("customers.xsd");
            return schemaFactory.newSchema(schemaResource);
        } catch (Exception e) {
            throw new XmlParsingException("Fehler beim Laden des XSD-Schemas", e);
        }
    }

    /**
     * Extrahiert Kundendaten aus einem DOM-Node.
     */
    private Customer extractCustomerFromNode(org.w3c.dom.Node node) {
        try {
            var element = (org.w3c.dom.Element) node;
            String id = getElementValue(element, "id");
            String name = getElementValue(element, "name");
            String email = getElementValue(element, "email");
            String phone = getElementValue(element, "phone");

            return new Customer(id, name, email, phone);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * Holt Textwert eines Elements.
     */
    private String getElementValue(org.w3c.dom.Element element, String tagName) {
        var nodeList = element.getElementsByTagName(tagName);
        if (nodeList.getLength() > 0) {
            return nodeList.item(0).getTextContent();
        }
        return "";
    }

    /**
     * Prüft ob der Name dem Suchbegriff entspricht.
     */
    private boolean matchesSearchTerm(String customerName, String searchTerm) {
        if (customerName == null || searchTerm == null) {
            return false;
        }
        return customerName.toLowerCase().contains(searchTerm.toLowerCase());
    }
}
