package com.example.parser;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.SAXParserFactory;

/**
 * Konfigurationssicherheit für XML-Parser.
 * 
 * Zentrale Stelle für alle Parser-Konfigurationen.
 * Stellt sicher, dass alle Parser konsistent XXE-geschützt sind.
 */
@Configuration
public class XmlParserConfig {

    /**
     * Erzeugt einen sicheren DocumentBuilderFactory.
     * 
     * Alle XXE-Schutzfeatures werden hier zentral definiert.
     */
    @Bean
    public DocumentBuilderFactory secureDocumentBuilderFactory() {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        try {
            // === XXE PREVENTION FEATURES ===

            // 1. DOCTYPE komplett verbieten (Hauptabwehr)
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

            // 2. Externe General Entities blockieren
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);

            // 3. Externe Parameter Entities blockieren
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

            // 4. Externe DTDs nicht laden
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // 5. XInclude deaktivieren
            factory.setXIncludeAware(false);

            // 6. Entity References nicht expandieren
            factory.setExpandEntityReferences(false);

            // 7. Secure Processing Mode aktivieren
            factory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // 8. Limitierte Entity Expansion (Billion Laughs Schutz)
            factory.setFeature("http://apache.org/xml/features/limit-entity-expansion", true);

        } catch (Exception e) {
            throw new RuntimeException("Fehler bei der Parser-Sicherheitskonfiguration", e);
        }

        return factory;
    }

    /**
     * Erzeugt einen sicheren SAXParserFactory.
     */
    @Bean
    public SAXParserFactory secureSAXParserFactory() {
        SAXParserFactory factory = SAXParserFactory.newInstance();

        try {
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            factory.setFeature(javax.xml.XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (Exception e) {
            throw new RuntimeException("Fehler bei der SAXParser-Sicherheitskonfiguration", e);
        }

        return factory;
    }
}
