"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Customer.java
package com.example.dto;

import java.io.Serializable;

/**
 * Data Transfer Object für Kundeninformationen.
 * 
 * Dieses DTO wird für die JSON-Ausgabe verwendet.
 * Enthält nur notwendige Felder (Prinzip der minimalen Information).
 */
public class Customer implements Serializable {

    private static final long serialVersionUID = 1L;

    private String id;
    private String name;
    private String email;
    private String phone;

    public Customer() {
    }

    public Customer(String id, String name, String email, String phone) {
        this.id = sanitizeField(id);
        this.name = sanitizeField(name);
        this.email = sanitizeField(email);
        this.phone = sanitizeField(phone);
    }

    // Getter und Setter
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = sanitizeField(id);
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = sanitizeField(name);
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = sanitizeField(email);
    }

    public String getPhone() {
        return phone;
    }

    public void setPhone(String phone) {
        this.phone = sanitizeField(phone);
    }

    /**
     * Führt einfache Sanisierung auf allen Feldern durch.
     * Entfernt potenziell gefährliche Zeichen.
     */
    private String sanitizeField(String value) {
        if (value == null) {
            return null;
        }
        // Entferne potenziell gefährliche XML/XML-Entitäts-Zeichen
        return value.replace("<", "&lt;")
                   .replace(">", "&gt;")
                   .replace("&", "&amp;")
                   .replace("\"", "&quot;")
                   .replace("'", "&apos;");
    }
}
