package com.example.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

/**
 * Spring Security Konfiguration für Basic Authentication.
 * 
 * Sicherheitsmaßnahmen:
 * - HTTP Basic Authentication für alle Endpunkte
 * - Sessionless (Stateless) für REST APIs
 * - Passwort-Hashing mit BCrypt
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    /**
     * Konfiguriert die Security Filter Chain.
     * 
     * - Alle /api/* Endpunkte benötigen Authentication
     * - Session ist stateless (für REST APIs empfohlen)
     * - CSRF ist disabled (da wir JSON verwenden)
     */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable())
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/customers").authenticated()
                .anyRequest().permitAll())
            .httpBasic(basic -> {});

        return http.build();
    }

    /**
     * Benutzer-Details Service mit In-Memory User Store.
     * 
     * In Production sollte dies auf eine Datenbank oder LDAP verweisen.
     */
    @Bean
    public UserDetailsService userDetailsService(PasswordEncoder passwordEncoder) {
        UserDetails adminUser = User.withUsername("admin")
            .password(passwordEncoder.encode("securePassword123"))
            .roles("ADMIN")
            .build();

        UserDetails userUser = User.withUsername("user")
            .password(passwordEncoder.encode("userPassword123"))
            .roles("USER")
            .build();

        return new InMemoryUserDetailsManager(adminUser, userUser);
    }

    /**
     * Password Encoder für sichere Hashes.
     * 
     * BCrypt ist kryptographisch stark und schützt vor Rainbow Tables.
     */
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
