 * Wird verwendet, um Parser-Fehler von allgemeinen Exceptions zu trennen.
 * Verhindert das Auslecken interner Details in Responses.
 */
public class XmlParsingException extends Exception {

    public XmlParsingException(String message) {
        super(message);
    }

    public XmlParsingException(String message, Throwable cause) {
        super(message, cause);
    }
}
