"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlValidationService.java
package com.example.secure.urlfetcher;

import java.net.InetAddress;
import java.net.URL;
import java.net.UnknownHostException;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Dient zur strengen Validierung von URLs, um SSRF (CWE-918) zu verhindern.
 * Prüft Schemata und resolved Hostnames gegen private IP-Bereiche.
 */
public class UrlValidationService {

    // Whitelist of approved domains - only these hosts are allowed
    private static final Set<String> ALLOWED_HOSTS = new HashSet<>(Arrays.asList(
        "api.trusted-service.com",
        "cdn.example.com",
        "data.external-partner.org"
    ));

    /**
     * Validiert die bereitgestellte URL.
     *
     * @param urlString Die zu validierende URL als String.
     * @throws InvalidUrlException Wenn die URL nicht sicher ist.
     */
    public void validateUrl(String urlString) throws InvalidUrlException {
        if (urlString == null || urlString.trim().isEmpty()) {
            throw new InvalidUrlException("URL darf nicht leer sein.");
        }

        try {
            URL url = new URL(urlString);

            // Nur HTTP und HTTPS erlauben (CWE-79 Prävention, Blockade von file://, gopher:// etc.)
            String protocol = url.getProtocol();
            if (!"http".equalsIgnoreCase(protocol) && !"https".equalsIgnoreCase(protocol)) {
                throw new InvalidUrlException("Nur http und https Protokolle sind erlaubt.");
            }

            String host = url.getHost();
            if (host == null || host.isEmpty()) {
                throw new InvalidUrlException("Host kann nicht leer sein.");
            }

            // Normalisiere den Hostnamen (entferne trailing dots, lowercase)
            host = host.toLowerCase().replaceAll("\\.$", "");

            // Whitelist-Prüfung - nur explizit erlaubte Hosts
            if (!ALLOWED_HOSTS.contains(host)) {
                throw new InvalidUrlException("Zugriff auf diesen Host ist nicht erlaubt.");
            }

            // IP-Auflösung durchführen, um DNS-Rebinding zu erkennen
            InetAddress[] addresses = InetAddress.getAllByName(host);

            for (InetAddress addr : addresses) {
                if (isPrivateIp(addr)) {
                    throw new InvalidUrlException("Zugriff auf private IP-Adressen ist verboten.");
                }

                // Zusätzliche Prüfung: IP darf nicht mit dem Hostnamen übereinstimmen
                // wenn es sich um eine private IP handelt
                String ipString = addr.getHostAddress();
                if (ipString.startsWith("0.") || ipString.startsWith("127.") || 
                    ipString.startsWith("10.") || ipString.startsWith("192.168.") ||
                    ipString.startsWith("172.16.") || ipString.startsWith("172.17.") ||
                    ipString.startsWith("172.18.") || ipString.startsWith("172.19.") ||
                    ipString.startsWith("172.20.") || ipString.startsWith("172.21.") ||
                    ipString.startsWith("172.22.") || ipString.startsWith("172.23.") ||
                    ipString.startsWith("172.24.") || ipString.startsWith("172.25.") ||
                    ipString.startsWith("172.26.") || ipString.startsWith("172.27.") ||
                    ipString.startsWith("172.28.") || ipString.startsWith("172.29.") ||
                    ipString.startsWith("172.30.") || ipString.startsWith("172.31.")) {
                    throw new InvalidUrlException("Zugriff auf private IP-Adressen ist verboten.");
                }
            }

            // Prüfe ob die URL keine versteckten Credentials enthält
            if (url.getUserInfo() != null) {
                throw new InvalidUrlException("URL darf keine Benutzerinformationen enthalten.");
            }

        } catch (UnknownHostException e) {
            throw new InvalidUrlException("Ungültiger Hostname.", e);
        } catch (Exception e) {
            // Generic catch to prevent information leakage during validation phase
            throw new InvalidUrlException("Die angegebene URL ist ungültig.");
        }
    }

    /**
     * Prüft, ob eine IP-Adresse einem privaten Bereich angehört.
     * Deckt Loopback, Link-Local, Site-Local und Multicast ab.
     */
    private boolean isPrivateIp(InetAddress address) {
        return address.isAnyLocalAddress() 
            || address.isLoopbackAddress() 
            || address.isLinkLocalAddress() 
            || address.isSiteLocalAddress() 
            || address.isMulticastAddress()
            || address.isMCGlobal()
            || address.isMCNodeLocal()
            || address.isMCLinkLocal()
            || address.isMCSiteLocal();
    }

    /**
     * Gibt die Whitelist der erlaubten Hosts zurück.
     * Kann für Monitoring-Zwecke verwendet werden.
     */
    public Set<String> getAllowedHosts() {
        return new HashSet<>(ALLOWED_HOSTS);
    }
}
