"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetcherController.java
package com.example.secure.urlfetcher;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST Controller für den URL Fetch Endpoint.
 * Enthält Autorisierung (@PreAuthorize) und Rate Limiting Integration.
 */
@RestController
public class UrlFetcherController {

    private final UrlValidationService urlValidationService;
    private final UrlFetchService urlFetchService;
    private final RateLimitService rateLimitService;

    @Autowired
    public UrlFetcherController(UrlValidationService urlValidationService, 
                                UrlFetchService urlFetchService, 
                                RateLimitService rateLimitService) {
        this.urlValidationService = urlValidationService;
        this.urlFetchService = urlFetchService;
        this.rateLimitService = rateLimitService;
    }

    /**
     * Endpunkt zum Abrufen von URL-Inhalten.
     * Erfordert Authentifizierung und Rate Limiting.
     */
    @GetMapping(value = "/api/fetch", produces = MediaType.TEXT_PLAIN_VALUE)
    @PreAuthorize("hasRole('USER')") // CWE-284: Zugriffskontrolle
    public ResponseEntity<String> fetchUrl(@RequestParam("url") String url) {

        // Rate Limiting prüfen
        if (!rateLimitService.allowRequest()) {
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS).body("Rate limit exceeded.");
        }

        try {
            // 1. Validierung (SSRF Schutz)
            urlValidationService.validateUrl(url);

            // 2. Fetching
            String content = urlFetchService.fetchContent(url);

            // 3. Rückgabe als Plain Text (XSS Mitigation)
            return ResponseEntity.ok(content);

        } catch (InvalidUrlException e) {
            // Wird vom GlobalExceptionHandler behandelt, hier nur Logging oder Weiterleitung
            throw e;
        } catch (UrlFetchException e) {
            throw e;
        } catch (Exception e) {
            // Fallback für unerwartete Fehler
            throw new RuntimeException("Ein interner Fehler ist aufgetreten.", e);
        }
    }
}
