"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.secure.urlfetcher;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Zentrale Ausnahmebehandlung gemäß CERT Rule ERR01-J.
 * Verhindert das Ausgeben sensibler Informationen (Stack Traces) an den Client.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger logger = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(InvalidUrlException.class)
    public ResponseEntity<ErrorResponse> handleInvalidUrl(InvalidUrlException ex) {
        // Internes Logging des tatsächlichen Fehlers (für Admins)
        logger.error("Invalid URL detected: {}", ex.getMessage(), ex);

        // Extern nur generische Nachricht (CWE-209)
        ErrorResponse error = new ErrorResponse(
            HttpStatus.BAD_REQUEST.value(),
            "Die angegebene URL ist ungültig oder nicht erlaubt.",
            "/api/fetch"
        );
        return ResponseEntity.badRequest().body(error);
    }

    @ExceptionHandler(UrlFetchException.class)
    public ResponseEntity<ErrorResponse> handleUrlFetch(UrlFetchException ex) {
        logger.error("Error fetching URL: {}", ex.getMessage(), ex);

        ErrorResponse error = new ErrorResponse(
            HttpStatus.INTERNAL_SERVER_ERROR.value(),
            "Fehler beim Abrufen der URL.",
            "/api/fetch"
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(error);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGenericException(Exception ex) {
        // Kritisch: Niemals ex.getMessage() oder StackTrace direkt an Client senden
        logger.error("Unhandled exception occurred", ex);

        ErrorResponse error = new ErrorResponse(
            HttpStatus.INTERNAL_SERVER_ERROR.value(),
            "Ein unerwarteter Fehler ist aufgetreten.",
            "/api/fetch"
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(error);
    }
}
