"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitFilter.java
package com.example.secure.urlfetcher;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Filter zur Begrenzung der Anfragen pro IP-Adresse (CWE-400).
 * Verhindert DoS-Angriffe durch einfache Token-Bucket-Logik.
 */
@Component
public class RateLimitFilter extends OncePerRequestFilter {

    private static final int MAX_REQUESTS = 10;
    private static final long TIME_WINDOW_MS = 60000; // 1 Minute

    // Speichert Anzahl der Requests pro IP
    private final Map<String, AtomicInteger> requestCounts = new ConcurrentHashMap<>();
    private final Map<String, Long> lastResetTime = new ConcurrentHashMap<>();

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {

        String ip = getClientIp(request);

        if (ip == null) {
            filterChain.doFilter(request, response);
            return;
        }

        long currentTime = System.currentTimeMillis();
        AtomicInteger count = requestCounts.computeIfAbsent(ip, k -> new AtomicInteger(0));
        Long resetTime = lastResetTime.getOrDefault(ip, currentTime);

        // Reset Counter wenn Zeitfenster abgelaufen
        if (currentTime - resetTime > TIME_WINDOW_MS) {
            count.set(0);
            lastResetTime.put(ip, currentTime);
        }

        // Prüfen ob Limit erreicht
        if (count.incrementAndGet() > MAX_REQUESTS) {
            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            response.getWriter().write("Rate limit exceeded.");
            return;
        }

        filterChain.doFilter(request, response);
    }

    private String getClientIp(HttpServletRequest request) {
        String xfHeader = request.getHeader("X-Forwarded-For");
        if (xfHeader != null) {
            return xfHeader.split(",")[0];
        }
        return request.getRemoteAddr();
    }
}
